export const legacyBodyHtml = "<div id=\"busy\"></div>\n<header id=\"hdr\" style=\"display:none\">\n  <div class=\"hwrap\">\n    <div class=\"brand\">\n      <div class=\"mark\"><i></i><i></i><i></i></div>\n      <div><b>AS CRM</b><small>Automation Systems NG</small></div>\n    </div>\n    <button class=\"nav-toggle\" id=\"navToggle\" onclick=\"document.getElementById('nav').classList.toggle('nav-open');this.setAttribute('aria-expanded',document.getElementById('nav').classList.contains('nav-open'))\" aria-label=\"Toggle navigation\" aria-expanded=\"false\">☰</button><nav id=\"nav\" role=\"navigation\" aria-label=\"Main navigation\">\n      <button data-v=\"dash\" onclick=\"nav('dash')\">Dashboard</button>\n      <button data-v=\"customers\" id=\"navCust\" onclick=\"nav('customers')\">Customers</button>\n      <button data-v=\"cases\" id=\"navCases\" onclick=\"nav('cases')\">Cases</button>\n      <button data-v=\"admin\" id=\"navAdmin\" style=\"display:none\" onclick=\"nav('admin')\">Admin</button>\n    </nav>\n    <div class=\"uchip\">\n      <div style=\"text-align:right\">\n        <div class=\"uname\" id=\"uName\"></div>\n        <div class=\"umail\" id=\"uMail\"></div>\n      </div>\n      <span class=\"rolebadge\" id=\"uRole\"></span>\n    </div>\n  </div>\n</header>\n\n<main id=\"main\" data-testid=\"crm-route\" data-route=\"dash\"></main>\n<button id=\"qlbtn\" style=\"display:none\" onclick=\"mQuickLog()\">＋ Quick log</button>\n\n<div id=\"mwrap\">\n  <div id=\"mcard\">\n    <div id=\"mhead\"><h2 id=\"mtitle\"></h2><button id=\"mx\" onclick=\"closeModal()\">✕</button></div>\n    <div id=\"mbody\"></div>\n    <div id=\"mfoot\"></div>\n  </div>\n</div>\n\n<div id=\"toast\"></div>";

export const legacyAppScript = "/* =====================================================================\n * AS CRM - client app. Pairs with the Next.js RPC server (/api/rpc transport).\n * =================================================================== */\nvar QREADS = { api_bootstrap:1, api_workspace:1, api_dashboard:1, api_getCase:1, api_getCustomer:1, api_searchCustomers:1, api_myCustomers:1, api_listCases:1, api_getQuotation:1, api_listTemplates:1, api_listAssignableUsers:1, api_admin_listUsers:1, api_admin_links:1 };\n\n/* ---------------------------------------------------------------------\n * Client-side store. Network calls still cost time, even with a fast Vercel server, so the app never waits on it: views render from\n * memory instantly and revalidate in the background (stale-while-\n * revalidate). Writes are optimistic. This is what makes it feel native.\n * ------------------------------------------------------------------- */\nvar CACHE = { customers:null, customersAt:0, cases:null, casesAt:0, casesKey:'', cust:{}, kase:{} };\nvar FRESH_MS = 90000;\nfunction fresh(at){ return at && (Date.now()-at) < FRESH_MS; }\nfunction sameData(a,b){ try{ return JSON.stringify(a)===JSON.stringify(b); }catch(e){ return false; } }\nfunction cacheBust(){ CACHE.customers=null; CACHE.cases=null; CACHE.cust={}; CACHE.kase={}; S.boot=null; }\nvar S = {\n  user:null, settings:null, route:'dash', routeArg:null, boot:null, bootAt:0,\n  /* P6: `mine` became two independent server flags, OR-combined. Neither set\n     means \"every case I can see\". */\n  custQ:'', caseF:{owned:false, assigned:false, stage:'', outcome:'Open', priority:'', q:''},\n  users:null, peers:[]\n};\n\n/* ---------------- tiny helpers ---------------- */\nfunction el(id){ return document.getElementById(id); }\nfunction setHtml(id, html){ var n = typeof id === 'string' ? el(id) : id; if(n) n.innerHTML = html; }\nfunction setText(id, txt){ var n = typeof id === 'string' ? el(id) : id; if(n) n.textContent = txt; }\nfunction setRouteAttr(name){ var m=el('main'); if(m) m.setAttribute('data-route', name); }\nfunction low(s){ return String(s===null||s===undefined?'':s).toLowerCase().trim(); }\n/* P9: \"Direct\" is a virtual account, never a real user row - it has no email\n   address and can never sign in. */\nfunction isDirectAccount(email){ return low(email)==='direct'; }\nfunction peerLabel(p){ return p.name + (p.hasLogin===false ? ' (no login)' : ''); }\nfunction esc(v){\n  return String(v===null||v===undefined?'':v)\n    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')\n    .replace(/\"/g,'&quot;').replace(/'/g,'&#39;');\n}\nfunction jsArg(v){ return esc(JSON.stringify(String(v===null||v===undefined?'':v))); }\nfunction jsJsonArg(v){ return esc(JSON.stringify(v)); }\nfunction fmtMoney(n){\n  var v = Number(n||0);\n  try{ return v.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}); }\n  catch(e){ return v.toFixed(2); }\n}\nfunction fmtShort(n){\n  var v = Number(n||0);\n  try{ return v.toLocaleString('en-IN',{maximumFractionDigits:0}); }catch(e){ return String(Math.round(v)); }\n}\nfunction fmtBytes(n){\n  var v = Number(n||0);\n  if(v < 1024) return v+' B';\n  if(v < 1024*1024) return (v/1024).toFixed(1)+' KB';\n  return (v/(1024*1024)).toFixed(1)+' MB';\n}\nfunction attachmentLinksHtml(list){\n  if(!list || !list.length) return '';\n  return '<div class=\"d\" style=\"margin-top:4px\">'+list.map(function(a){ return '<a href=\"'+esc(a.viewLink)+'\" target=\"_blank\" rel=\"noopener\">'+esc(a.fileName)+'</a>'; }).join(' · ')+'</div>';\n}\n/* Keyed on the handover's activity id, which getCase returns alongside the\n   note itself. The attachments map is keyed by activity id and is NOT capped,\n   unlike d.history - matching on note text through history worked only while\n   the case had fewer than 40 activity entries, then silently rendered no\n   links at all. */\nfunction latestNoteAttachments(d){\n  var id = d.latestHandoverActivityId;\n  if(!id) return [];\n  return (d.attachments && d.attachments[id]) || [];\n}\nfunction moneyCell(cur,n){\n  if(n===''||n===null||n===undefined) return '<span class=\"sub\">—</span>';\n  return '<span class=\"money\">'+esc(cur||'INR')+' '+fmtMoney(n)+'</span>';\n}\nfunction errMsg(e){\n  var m = (e && e.message) ? e.message : String(e);\n  return m.replace(/^(Error|Exception|ScriptError):\\s*/,'');\n}\nvar busyN = 0;\nfunction busy(on){ busyN += on?1:-1; if(busyN<0) busyN=0; el('busy').className = busyN>0?'on':''; }\nvar SWR_CACHE = {};\nvar WRITE_PURGES = {\n  saveCustomer: ['getCustomersGrid','getDashboardData','getCustomerDetail'],\n  saveCase: ['getCases','getDashboardData','getCustomerDetail'],\n  updateContact: ['getCustomerDetail','getCustomersGrid'],\n  deleteCustomer: ['getCustomersGrid','getDashboardData'],\n  saveQuotation: ['getCases','getDashboardData'],\n  purgeCust: ['getCustomersGrid','getDashboardData']\n};\n\nfunction cacheBustKey(fn) {\n  if (WRITE_PURGES[fn]) {\n    WRITE_PURGES[fn].forEach(function(k) {\n      Object.keys(SWR_CACHE).forEach(function(ck) {\n        if (ck.indexOf(k) === 0) delete SWR_CACHE[ck];\n      });\n    });\n  } else {\n    SWR_CACHE = {};\n  }\n}\n\n// cacheBustKey() only purges this file's SWR_CACHE. The original legacy\n// client (docs/source-appscript/Index.html) has its OWN separate cache -\n// the global CACHE object (CACHE.customers/cases/cust/kase) used by\n// vCustomer/vCase/vDash for a 90s stale-while-revalidate render - and its\n// own gs() called cacheBust() (defined in that source file) on every write\n// to clear it. This generator fully replaces that gs(), so cacheBust()\n// must be called here too, or a save on a detail view the user is already\n// looking at (which is therefore \"fresh\" in CACHE) renders stale data\n// until CACHE.FRESH_MS (90s) elapses or the page is hard-refreshed.\n\nfunction gs(fn){\n  var args = Array.prototype.slice.call(arguments,1);\n  var ck = fn + ':' + JSON.stringify(args);\n  if (QREADS[fn] && SWR_CACHE[ck] && (Date.now() - SWR_CACHE[ck].ts < 30000)) {\n    return Promise.resolve(SWR_CACHE[ck].data);\n  }\n\n  busy(true);\n  return new Promise(function(res,rej){\n    var done=false;\n    var timer=setTimeout(function(){ if(done)return; done=true; busy(false); rej(new Error('This is taking longer than usual - tap Retry.')); }, 30000);\n    window.__AS_CRM_FETCH__('/api/rpc', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ fn: fn, args: args })\n    })\n      .then(function(response){ return response.json(); })\n      .then(function(payload){\n        if(done)return;\n        done=true;\n        clearTimeout(timer);\n        busy(false);\n        if(!payload || payload.ok===false){ rej(new Error((payload && payload.error) || 'Request failed.')); return; }\n        if(QREADS[fn]) { SWR_CACHE[ck] = { ts: Date.now(), data: payload.data }; }\n        else { cacheBustKey(fn); cacheBust(); }\n        res(payload.data);\n      })\n      .catch(function(e){ if(done)return; done=true; clearTimeout(timer); busy(false); rej(e); });\n  });\n}\nvar toastT = null;\nfunction toast(msg, isErr){\n  var t = el('toast'); t.textContent = msg; t.className = 'on'+(isErr?' err':'');\n  clearTimeout(toastT); toastT = setTimeout(function(){ t.className=''; }, isErr?5200:3400);\n}\nfunction oops(e){\n  var msg = errMsg(e);\n  if(msg && (msg.indexOf('Cannot set properties of null') > -1 || msg.indexOf(\"setting 'innerHTML'\") > -1 || msg.indexOf(\"setting 'textContent'\") > -1)){ return; }\n  toast(msg, true);\n}\nfunction todayISO(){ var d=new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }\n\n/* ---------------- modal ---------------- */\nfunction openModal(title, bodyHTML, footHTML, wide){\n  setText('mtitle', title);\n  setHtml('mbody', bodyHTML);\n  setHtml('mfoot', footHTML || '');\n  el('mcard').className = wide?'wide':'';\n  el('mwrap').className = 'on';\n}\nfunction closeModal(){ el('mwrap').className=''; setHtml('mbody', ''); setHtml('mfoot', ''); }\nel('mwrap').addEventListener('click', function(ev){ if(ev.target===el('mwrap')) closeModal(); });\ndocument.addEventListener('keydown', function(ev){ if(ev.key==='Escape') closeModal(); });\nfunction v(id){ var n = el(id); return n ? n.value.trim() : ''; }\n\n/* ---------------- chips ---------------- */\nfunction tagChips(tags){\n  if(!tags || !tags.length) return '<span class=\"sub\">—</span>';\n  return tags.map(function(t){ return '<span class=\"chip\">'+esc(t)+'</span>'; }).join('');\n}\nfunction stageChip(stage){ return '<span class=\"badge b-blue\">'+esc(stage||'—')+'</span>'; }\nfunction outcomeChip(o){\n  var k = o==='Won'?'b-green':(o==='Lost'?'b-red':(o==='Hold'?'b-amber':'b-grey'));\n  return '<span class=\"badge '+k+'\">'+esc(o)+'</span>';\n}\nfunction caseStatusChip(stage, outcome){ return outcome ? outcomeChip(outcome) : stageChip(stage); }\nfunction priChip(p){\n  if(!p) return '';\n  var k = p==='High'?'b-red':(p==='Medium'?'b-amber':'b-grey');\n  return '<span class=\"badge '+k+'\">'+esc(p)+'</span>';\n}\nfunction typeChip(t){ return t ? '<span class=\"badge b-grey\">'+esc(t)+'</span>' : ''; }\nfunction qStatusChip(s){\n  var k = s==='Accepted'?'b-green':(s==='Rejected'?'b-red':(s==='Sent'?'b-blue':(s==='Superseded'?'b-grey':'b-amber')));\n  return '<span class=\"badge '+k+'\">'+esc(s)+'</span>';\n}\nfunction accessBadge(a){\n  return a==='FULL' ? '<span class=\"badge b-green\">Full access</span>' : '<span class=\"badge b-grey\">Name only</span>';\n}\n\n/* ---------------- pickers ---------------- */\nfunction tgTag(btn){ btn.className = btn.className==='on'?'':'on'; }\nfunction tagPickerHTML(id, all, selected, withStar){\n  var sel = selected||[];\n  var html = '<div class=\"tagpick\" id=\"'+id+'\">';\n  if(withStar) html += '<button type=\"button\" data-t=\"*\" class=\"'+(sel.indexOf('*')>-1?'on':'')+'\" onclick=\"tgTag(this)\">All tags (*)</button>';\n  (all||[]).forEach(function(t){\n    html += '<button type=\"button\" data-t=\"'+esc(t)+'\" class=\"'+(sel.indexOf(t)>-1?'on':'')+'\" onclick=\"tgTag(this)\">'+esc(t)+'</button>';\n  });\n  return html+'</div>';\n}\nfunction multiPickHTML(id, items, sel){\n  sel = sel||[];\n  var html = '<div class=\"tagpick\" id=\"'+id+'\">';\n  (items||[]).forEach(function(it){\n    html += '<button type=\"button\" data-t=\"'+esc(it.val)+'\" class=\"'+(sel.indexOf(it.val)>-1?'on':'')+'\" onclick=\"tgTag(this)\">'+esc(it.label)+'</button>';\n  });\n  return html+'</div>';\n}\nfunction pickerVal(id){\n  var out = []; var n = el(id); if(!n) return out;\n  n.querySelectorAll('button.on').forEach(function(b){ out.push(b.getAttribute('data-t')); });\n  return out;\n}\n/* ---------------- SEI (P8) ----------------\n   customers.sei is a string[] chosen from an admin-managed list. The manager\n   asked specifically for a DROPDOWN multi-select here, not the pill/tagpick\n   style used by locations, so this is a real <select multiple>. Zero\n   selections is valid - the field is optional.\n   The selectable names only ride along on the customer-grid metadata, so they\n   are cached globally the first time any grid payload arrives. */\nvar SEINAMES = [];\nfunction noteSeiNames(d){ if(d && d.seiNames) SEINAMES = d.seiNames; }\n/* Tolerates the pre-migration free-text shape as well as the array. */\nfunction seiList(val){\n  if(!val) return [];\n  if(typeof val === 'string') return val ? [val] : [];\n  return val;\n}\nfunction seiOptions(sel){\n  var out = (SEINAMES||[]).slice();\n  seiList(sel).forEach(function(s){ if(out.indexOf(s)<0) out.push(s); });\n  return out;\n}\nfunction seiSelectHTML(id, cls, sel, attrs){\n  var chosen = seiList(sel), names = seiOptions(sel);\n  var html = '<select multiple size=\"1\"'+(id?' id=\"'+id+'\"':'')+' class=\"sei'+(cls?' '+cls:'')+'\"'+(attrs||'')+'>';\n  names.forEach(function(n){\n    html += '<option value=\"'+esc(n)+'\"'+(chosen.indexOf(n)>-1?' selected':'')+'>'+esc(n)+'</option>';\n  });\n  return html+'</select>';\n}\nfunction seiFieldHTML(sel){\n  if(!seiOptions(sel).length) return '<div class=\"sub\" style=\"padding:9px 0\">No SEI names configured yet.</div>';\n  return seiSelectHTML('f_sei', '', sel, '')+'<p class=\"hint\">Optional. Hold Ctrl/Cmd to pick more than one.</p>';\n}\nfunction seiSelectedValues(node){\n  if(!node) return [];\n  var out = [];\n  [].slice.call(node.options||[]).forEach(function(o){ if(o.selected) out.push(o.value); });\n  return out;\n}\nfunction seiVal(id){ return seiSelectedValues(el(id)); }\n\nfunction selOptions(list, sel){\n  return (list||[]).map(function(o){ return '<option'+(o===sel?' selected':'')+'>'+esc(o)+'</option>'; }).join('');\n}\nfunction userSelectHTML(id, selEmail){\n  var sel = low(selEmail||(S.user?S.user.email:''));\n  var html = '<select id=\"'+id+'\">';\n  (S.users||[]).forEach(function(u){\n    html += '<option value=\"'+esc(u.email)+'\"'+(low(u.email)===sel?' selected':'')+'>'+esc(u.name)+(low(u.email)===low(S.user.email)?' (me)':'')+'</option>';\n  });\n  return html+'</select>';\n}\nfunction catPickItems(){ return (S.settings.categories||[]).map(function(c){ return {val:c, label:c}; }); }\nfunction userPickItems(){ return (S.users||[]).map(function(u){ return {val:u.email, label:u.name+(low(u.email)===low(S.user.email)?' (me)':'')}; }); }\n\n/* ---------------- level helpers ---------------- */\nfunction lvl(){ return S.user ? Number(S.user.level||1) : 1; }\nfunction isAdmin(){ return lvl()>=6; }\nfunction isBackend(){ return lvl()>=5; }   // L5/L6 — no personal sales performance dashboard\nfunction canAssign(){ return lvl()>=2; }\n\nfunction ensureUsers(){\n  if(S.users) return Promise.resolve(S.users);\n  return gs('api_listAssignableUsers').then(function(list){ S.users = list; return list; });\n}\n\n/* ---------------- boot / lock ---------------- */\nfunction renderLock(){\n  var r = String(BOOT.reason||'');\n  var msg, title='Access pending';\n  if(r.indexOf('NOT_REGISTERED:')===0){ msg = r.replace('NOT_REGISTERED:','').trim(); title = 'You are not registered yet'; }\n  else if(r.indexOf('Setup pending')>-1){ title = 'Setup pending'; msg = 'The CRM database has not been created yet. Apply the Supabase migrations and seed the CRM settings, then reload this page.'; }\n  else{ msg = r || 'Could not sign you in.'; }\n  setHtml('main', '<div class=\"lockcard\"><div class=\"mark\" style=\"margin:0 auto 16px\"><i></i><i></i><i></i></div>'+\n    '<h1>'+esc(title)+'</h1><p class=\"sub\" style=\"margin-bottom:18px\">'+esc(msg)+'</p>'+\n    (BOOT.email?'<p class=\"mono sub\" style=\"margin-bottom:18px\">Signed in as '+esc(BOOT.email)+'</p>':'')+\n    '<button class=\"btn\" onclick=\"location.reload()\">Reload</button></div>');\n}\n\nfunction bootstrap(force){\n  if(!force && S.boot && (Date.now()-S.bootAt)<45000) return Promise.resolve(S.boot);\n  return gs('api_bootstrap').then(function(d){ S.boot=d; S.bootAt=Date.now(); return d; });\n}\n// Warm the whole app in a single call so the first tab switch costs nothing.\nfunction warm(){\n  return gs('api_workspace', S.caseF).then(function(w){\n    if(w.boot){ S.boot=w.boot; S.bootAt=Date.now(); }\n    if(w.customers){ CACHE.customers=w.customers; CACHE.customersAt=Date.now(); noteSeiNames(w.customers); }\n    if(w.cases){ CACHE.cases=w.cases; CACHE.casesAt=Date.now(); CACHE.casesKey=JSON.stringify(S.caseF); }\n    return w.boot;\n  });\n}\nfunction init(){\n  warm().then(function(d){\n    S.user = d.user; S.settings = d.settings; S.peers = d.peers||[];\n    setText('uName', d.user.name);\n    setText('uMail', d.user.email);\n    setText('uRole', d.user.role);\n    if(d.nav && d.nav.admin) el('navAdmin').style.display='';\n    if(d.isL1){ el('navCust').style.display='none'; el('navCases').style.display='none'; }\n    if(lvl()>=2) el('qlbtn').style.display='';\n    el('hdr').style.display='';\n    vDash(d);\n  }).catch(function(e){\n    el('hdr').style.display='none';\n    BOOT = { ok:false, reason:errMsg(e), email:(BOOT && BOOT.email) || '' };\n    window.BOOT = BOOT;\n    renderLock();\n  });\n}\n\nfunction setTab(name){\n  document.querySelectorAll('#nav button').forEach(function(b){ b.className = b.getAttribute('data-v')===name ? 'on':''; });\n}\nfunction nav(name, arg){\n  if(name==='dash') vDash();\n  else if(name==='customers') vCustomers();\n  else if(name==='customer') vCustomer(arg);\n  else if(name==='case') vCase(arg);\n  else if(name==='cases') vCases();\n  else if(name==='admin') vAdmin();\n}\n\n/* =====================================================================\n * DASHBOARD\n * =================================================================== */\nfunction vDash(pre){\n  S.route='dash'; setRouteAttr('dash'); S.routeArg=null; setTab('dash');\n  setHtml('main', '<div class=\"sub\">Loading dashboard…</div>');\n  var p = pre ? Promise.resolve(pre) : bootstrap();\n  p.then(function(d){\n    S.user = d.user; S.settings = d.settings; S.peers = d.peers||[];\n    if(d.isL1){ renderL1Dash(d); return; }\n    if(d.isBackend || isBackend()){ renderBackendDash(d); return; }\n\n    var html = '<div class=\"pagehead\"><div class=\"grow\"><h1>Dashboard</h1>'+\n      '<div class=\"sub\">Your performance and open work.</div></div>';\n    if(S.peers.length){\n      html += '<div><label>Whose dashboard</label><select id=\"dashWho\" onchange=\"switchDash()\"><option value=\"\">Me ('+esc(S.user.name)+')</option>'+\n        S.peers.map(function(p){ return '<option value=\"'+esc(p.email)+'\">'+esc(peerLabel(p))+'</option>'; }).join('')+'</select></div>';\n    } else if(lvl()>=3){\n      html += '<div class=\"sub\" style=\"align-self:center\">No other users to view yet.</div>';\n    }\n    /* P5: the \"+ New customer\" button that used to sit here duplicated the\n       Customers tab in the top nav, so it was removed. */\n    html += '</div>';\n    html += '<div id=\"dashBlocks\"></div>';\n    html += '<div class=\"card\"><div class=\"ovl\">Recent activity</div>'+ recentHTML(d.recent) +'</div>';\n    setHtml('main', html);\n    setHtml('dashBlocks', dashBlocksHTML(d.self, low(S.user.email), false));\n  }).catch(oops);\n}\n\nfunction switchDash(){\n  var who = v('dashWho');\n  if(!who){\n    if(isBackend()){ setHtml('dashBlocks', backendPrompt()); return; }\n    bootstrap().then(function(d){ setHtml('dashBlocks', dashBlocksHTML(d.self, low(S.user.email), false)); }).catch(oops);\n    return;\n  }\n  gs('api_dashboard', who).then(function(r){\n    setHtml('dashBlocks', '<div class=\"card\" style=\"border-left:4px solid var(--blue);padding:12px 16px\"><b>Viewing '+esc(r.subject.name)+'</b> <span class=\"sub\">read only</span></div>'+\n      dashBlocksHTML(r.dash, low(r.subject.email), true));\n  }).catch(oops);\n}\n\n/* ---- L5/L6 back-office dashboard: no personal sales stats ---- */\nfunction backendPrompt(){\n  return S.peers.length\n    ? '<div class=\"card\"><div class=\"empty\">Select a user above to view their dashboard.</div></div>'\n    : '<div class=\"card\"><div class=\"empty\">No sales users to display yet.</div></div>';\n}\nfunction renderBackendDash(d){\n  var html = '<div class=\"pagehead\"><div class=\"grow\"><h1>Overview</h1>'+\n    '<div class=\"sub\">Back-office view — full access across all locations, no personal sales targets.</div></div>';\n  if(S.peers.length){\n    html += '<div><label>View a user\\u2019s dashboard</label><select id=\"dashWho\" onchange=\"switchDash()\"><option value=\"\">\\u2014 select a user \\u2014</option>'+\n      S.peers.map(function(p){ return '<option value=\"'+esc(p.email)+'\">'+esc(peerLabel(p))+'</option>'; }).join('')+'</select></div>';\n  }\n  /* P5: the Customers, Cases and Admin buttons that used to sit here all\n     duplicated the top nav and were removed. Admin went in a second pass -\n     the manager's note named only the first two, but it routes to the same\n     tab as #navAdmin, so it was the same duplication. */\n  html += '</div>';\n  html += '<div id=\"dashBlocks\">'+backendPrompt()+'</div>';\n  html += '<div class=\"card\"><div class=\"ovl\">Recent activity</div>'+ recentHTML(d.recent) +'</div>';\n  setHtml('main', html);\n}\n\nfunction dashBlocksHTML(dash, subjectEmail, readOnly){\n  var s = dash.stats;\n  var html = '<div class=\"stats\">'+\n    '<div class=\"stat\" onclick=\"goCases({owned:true,outcome:\\'Open\\'})\"><div class=\"n\">'+s.myCustomers+'</div><div class=\"t\">My customers</div></div>'+\n    '<div class=\"stat\" onclick=\"goCases({owned:true,outcome:\\'Open\\'})\"><div class=\"n\">'+s.openOpps+'</div><div class=\"t\">Open cases</div></div>'+\n    '<div class=\"stat\"><div class=\"n\">'+esc(S.settings.currency)+' '+fmtShort(s.wonMonthValue)+'</div><div class=\"t\">Won this month</div><div class=\"x\">'+s.wonMonthCount+' order'+(s.wonMonthCount===1?'':'s')+'</div></div>'+\n    '<div class=\"stat\"><div class=\"n\">'+esc(S.settings.currency)+' '+fmtShort(s.won2wValue)+'</div><div class=\"t\">Won — last 2 weeks</div><div class=\"x\">'+s.won2wCount+' order'+(s.won2wCount===1?'':'s')+'</div></div>'+\n    '</div>';\n\n  html += '<div class=\"row\"><div class=\"col\"><div class=\"card\"><div class=\"ovl\">Opportunity tickets \\u2014 assigned to me</div>'+ openCasesHTML(dash.tickets||dash.cases) +'</div></div></div>';\n  return html;\n}\n\nfunction caseValueCell(o){\n  var cur=S.settings.currency;\n  if(o.outcome==='Won') return moneyCell(cur,o.orderValue);\n  if(o.quotedValue!=='' && o.quotedValue!=null && Number(o.quotedValue)>0)\n    return '<span class=\"sub\" style=\"font-weight:400\">quoted </span>'+moneyCell(cur,o.quotedValue);\n  return moneyCell(cur,'');\n}\nfunction openCasesHTML(list){\n  if(!list || !list.length) return '<div class=\"empty\">No open cases assigned to you.</div>';\n  return list.map(function(c){\n    return '<div class=\"qr\"><div style=\"flex:1;min-width:150px;cursor:pointer\" onclick=\"nav(\\'case\\','+jsArg(c.id)+')\"><b>'+esc(c.title)+'</b>'+\n      '<div class=\"sub\">'+esc(c.customerName)+'</div></div>'+stageChip(c.stage)+priChip(c.priority)+\n      '<button class=\"btn ghost sm\" onclick=\"event.stopPropagation();mAssign('+jsArg(c.id)+')\">Reassign</button></div>';\n  }).join('');\n}\nfunction recentHTML(recent){\n  if(!recent || !recent.length) return '<div class=\"empty\">Nothing yet.</div>';\n  var html = '<ul class=\"tlx\">';\n  recent.forEach(function(r){\n    html += '<li><div class=\"w\">'+esc(r.when)+' · '+esc(r.who)+' · '+esc(r.action)+'</div><div class=\"d\">'+esc(r.details||r.entity)+'</div></li>';\n  });\n  return html+'</ul>';\n}\nfunction goCases(f){ S.caseF = {owned:!!(f.owned||f.mine), assigned:!!f.assigned, stage:f.stage||'', outcome:f.outcome||'', priority:'', q:''}; vCases(); }\n\n/* ---- L1 minimal dashboard ---- */\nfunction renderL1Dash(d){\n  var t = (d.self && (d.self.tickets || d.self.cases)) || [];\n  var html = '<div class=\"pagehead\"><div class=\"grow\"><h1>My work</h1><div class=\"sub\">Opportunity tickets assigned to you \\u2014 open one to work it and update its stage.</div></div></div>';\n  html += '<div class=\"card\"><div class=\"ovl\">My opportunity tickets</div>'+ openCasesHTML(t) +'</div>';\n  setHtml('main', html);\n}\n\n/* =====================================================================\n * CUSTOMERS — search + list\n * =================================================================== */\nvar searchT = null;\nfunction vCustomers(){\n  S.route='customers'; setRouteAttr('customers'); S.routeArg=null; setTab('customers');\n  setHtml('main', '<div class=\"pagehead\"><div class=\"grow\"><h1>Customers</h1><div class=\"sub\">Search first — if the customer isn\\'t there, create it from the search result.</div></div></div>'+\n    '<div class=\"card\"><label>Search customers by name, location, type or area</label><input id=\"custQ\" value=\"'+esc(S.custQ)+'\" oninput=\"custTyped()\"></div>'+\n    '<div id=\"custBody\"></div>');\n  el('custQ').focus();\n  custApply();\n}\nfunction custTyped(){ S.custQ=v('custQ'); clearTimeout(searchT); searchT=setTimeout(custApply, 300); }\nfunction custApply(){\n  var q=v('custQ'); S.custQ=q;\n  if(q.length===0){ loadGrid(); return; }\n  if(q.length<2){ setHtml('custBody', '<div class=\"card\"><div class=\"empty\">Keep typing — at least 2 characters.</div></div>'); return; }\n  runSearch(q);\n}\nfunction createBar(q){\n  return '<div class=\"qr\" style=\"border-color:var(--brand);background:#F6FAF7;margin-bottom:12px\">'+\n    '<div style=\"flex:1;min-width:170px\"><b>Not in the list?</b><div class=\"sub\">Create a new customer named \"'+esc(q)+'\".</div></div>'+\n    '<button class=\"btn\" onclick=\"mNewCustomer('+jsArg(q)+')\">+ Create \"'+esc(q)+'\"</button></div>';\n}\nfunction runSearch(q){\n  setHtml('custBody', '<div class=\"card\"><div class=\"sub\">Searching…</div></div>');\n  gs('api_searchCustomers', q).then(function(list){\n    if(v('custQ')!==q) return;\n    if(!list.length){\n      setHtml('custBody', '<div class=\"card\"><div class=\"empty\">No customers match \"'+esc(q)+'\".</div>'+createBar(q)+'</div>');\n      return;\n    }\n    var html='<div class=\"ovl\">Search results</div>'+createBar(q)+'<div style=\"overflow-x:auto\"><table><tr><th>Customer</th><th>Location</th><th>Type</th><th>Priority</th><th>Handlers</th><th></th></tr>';\n    list.forEach(function(c){\n      var extra = c.access==='FULL' ? '<div class=\"sub\">'+esc(c.area||'')+'</div>' : '';\n      var click = c.access==='FULL' ? 'nav(\\'customer\\','+jsArg(c.id)+')' : 'mRestricted('+jsArg(c.id)+')';\n      html += '<tr class=\"clk\" onclick=\"'+click+'\"><td><b>'+esc(c.name)+'</b>'+extra+'</td><td>'+tagChips(c.tags)+'</td>'+\n        '<td>'+(typeChip(c.type)||'<span class=\"sub\">—</span>')+'</td><td>'+(priChip(c.priority)||'<span class=\"sub\">—</span>')+'</td>'+\n        '<td class=\"sub\">'+esc((c.handlers||[]).join(', ')||'—')+'</td><td>'+accessBadge(c.access)+'</td></tr>';\n    });\n    setHtml('custBody', '<div class=\"card\">'+html+'</table></div><div class=\"hint\">Showing up to 80 results.</div></div>');\n  }).catch(function(e){ setHtml('custBody', '<div class=\"card\"><div class=\"empty\">'+esc(errMsg(e))+'</div></div>'); });\n}\n\nvar MCBLANK='__BLANK__';   // sentinel for \"filter to empty values\" (HTML-safe)\nvar MC=null, MCHSEL=[], MCSEL={};\nvar MCFILT={name:'',tag:'',type:'',priority:'',area:'',sei:'',remarks:'',contacts:'',handler:''};\nfunction gridIsAll(){ return lvl()>=5; }\nfunction otherHandlers(c){ return (c.handlers||[]).filter(function(h){ return low(h.email)!==low(S.user.email); }); }\nfunction allHandlerObjs(){\n  var seen={}, out=[];\n  (MC?MC.customers:[]).forEach(function(c){ (c.handlers||[]).forEach(function(h){ var k=low(h.email); if(!seen[k]){ seen[k]=1; out.push({email:k,name:h.name}); } }); });\n  out.sort(function(a,b){ return a.name<b.name?-1:1; });\n  return out;\n}\nfunction mcOtherHandlerList(){\n  var seen={}, out=[];\n  (MC?MC.customers:[]).forEach(function(c){ otherHandlers(c).forEach(function(h){ if(!seen[h.email]){ seen[h.email]=1; out.push(h); } }); });\n  out.sort(function(a,b){ return a.name<b.name?-1:1; });\n  return out;\n}\nfunction gridShell(inner){\n  var all=gridIsAll();\n  setHtml('custBody', '<div class=\"card\"><div class=\"ovl\">'+(all?'All customers':'My customers')+' <span id=\"mcCount\" class=\"sub\"></span>'+\n    (all?' <button class=\"btn ghost sm\" style=\"margin-left:8px\" onclick=\"loadAllCustomers(true)\">Refresh</button>':'')+'</div>'+\n    '<p class=\"hint\" style=\"margin-top:-4px\">'+(all?'Every customer in the database. Handlers are the owners; a customer with no user yet shows \"Direct\".':'Customers you handle. Edit cells inline — changes save automatically.')+'</p>'+\n    '<div id=\"mcWrap\">'+inner+'</div></div>');\n}\nfunction gridBusy(){\n  if(Object.keys(PENDING).length) return true;\n  var a=document.activeElement;\n  return !!(a && a.className && String(a.className).indexOf('ce')>-1);\n}\nfunction loadGrid(force){ if(gridIsAll()) loadAllCustomers(force); else loadMyCustomers(); }\nfunction loadMyCustomers(){\n  MCSEL={};\n  var have=(CACHE.customers && CACHE.customers.scope==='mine')?CACHE.customers:null;\n  if(have){ MC=have; gridShell(''); renderMyCustomers(); }\n  else gridShell('<div class=\"sub\">Loading…</div>');\n  if(have && fresh(CACHE.customersAt)) return;\n  gs('api_myCustomers').then(function(d){\n    CACHE.customers=d; CACHE.customersAt=Date.now(); noteSeiNames(d);\n    if(S.route!=='customers' || v('custQ')) return;\n    if(gridBusy()){ MC=d; return; }\n    if(sameData(MC,d)){ MC=d; return; }\n    MC=d; if(!el('mcWrap')) gridShell(''); renderMyCustomers();\n  }).catch(function(e){\n    if(have) return;\n    if(el('mcWrap')) setHtml('mcWrap', '<div class=\"empty\">'+esc(errMsg(e))+'<div style=\"margin-top:10px\"><button class=\"btn ghost sm\" onclick=\"loadMyCustomers()\">Retry</button></div></div>');\n  });\n}\nfunction loadAllCustomers(force){\n  MCSEL={};\n  var have=(CACHE.customers && CACHE.customers.scope==='all')?CACHE.customers:null;\n  if(!force && !have){\n    setHtml('custBody', '<div class=\"card\"><div class=\"ovl\">All customers</div>'+\n      '<p class=\"hint\" style=\"margin-top:-4px\">The full customer list can be large, so it is fetched only when you ask (search above works without fetching).</p>'+\n      '<button class=\"btn\" onclick=\"loadAllCustomers(true)\">Fetch all customers</button></div>');\n    return;\n  }\n  if(have){ MC=have; gridShell(''); renderMyCustomers(); }\n  else gridShell('<div class=\"sub\">Fetching…</div>');\n  gs('api_allCustomers').then(function(d){\n    CACHE.customers=d; CACHE.customersAt=Date.now(); noteSeiNames(d);\n    if(S.route!=='customers' || v('custQ')) return;\n    if(gridBusy()){ MC=d; return; }\n    if(have && sameData(MC,d)){ MC=d; return; }\n    MC=d; if(!el('mcWrap')) gridShell(''); renderMyCustomers();\n  }).catch(function(e){\n    if(have) return;\n    if(el('mcWrap')) setHtml('mcWrap', '<div class=\"empty\">'+esc(errMsg(e))+'<div style=\"margin-top:10px\"><button class=\"btn ghost sm\" onclick=\"loadAllCustomers(true)\">Retry</button></div></div>');\n  });\n}\nfunction mcTextMatch(val,f){ return !f || low(val||'').indexOf(low(f))>-1; }\nfunction mcFiltered(){\n  if(!MC) return [];\n  var all=gridIsAll();\n  return MC.customers.filter(function(c){\n    if(!mcTextMatch(c.name,MCFILT.name)) return false;\n    if(!mcTextMatch(c.area,MCFILT.area)) return false;\n    if(!mcTextMatch(seiList(c.sei).join(', '),MCFILT.sei)) return false;\n    if(!mcTextMatch(c.remarks,MCFILT.remarks)) return false;\n    if(MCFILT.tag){ if(MCFILT.tag===MCBLANK){ if((c.tags||[]).length) return false; } else if((c.tags||[]).indexOf(MCFILT.tag)<0) return false; }\n    if(MCFILT.type){ if(MCFILT.type===MCBLANK){ if(c.type) return false; } else if(c.type!==MCFILT.type) return false; }\n    if(MCFILT.priority){ if(MCFILT.priority===MCBLANK){ if(c.priority) return false; } else if(c.priority!==MCFILT.priority) return false; }\n    if(MCFILT.contacts==='0' && (c.contacts||0)!==0) return false;\n    if(MCFILT.contacts==='1' && (c.contacts||0)===0) return false;\n    if(all){\n      if(MCHSEL.length){ var he=(c.handlers||[]).map(function(h){ return low(h.email); }); for(var i=0;i<MCHSEL.length;i++){ if(he.indexOf(low(MCHSEL[i]))<0) return false; } }\n    } else if(MCFILT.handler){\n      var oth=otherHandlers(c).map(function(h){ return low(h.email); });\n      if(MCFILT.handler===MCBLANK){ if(oth.length) return false; } else if(oth.indexOf(low(MCFILT.handler))<0) return false;\n    }\n    return true;\n  });\n}\nfunction mcSelCount(){ return Object.keys(MCSEL).filter(function(id){ return MCSEL[id]; }).length; }\nfunction renderMyCustomers(){\n  if(!el('mcWrap')) return;\n  var d=MC, all=gridIsAll();\n  noteSeiNames(d);\n  if(el('mcCount')) setText('mcCount', '('+d.total+')');\n  if(!d.customers.length){\n    setHtml('mcWrap', '<div class=\"empty\">'+(all?'No customers in the database yet.':'You don\\'t handle any customers yet.<br>Search above and create one from the search result, or ask a handler to add you to theirs.')+'</div>');\n    return;\n  }\n  var canPri=d.canEditPriority, canCls=d.canEditClass, canDel=d.canDelete;\n  function eopts(list,val){ return '<option value=\"\">—</option>'+list.map(function(t){ return '<option'+(t===val?' selected':'')+'>'+esc(t)+'</option>'; }).join(''); }\n  function fsel(field,list){\n    return '<select class=\"fx\" onchange=\"mcSetFilter(\\''+field+'\\',this.value)\"><option value=\"\">All</option>'+\n      list.map(function(t){ return '<option value=\"'+esc(t)+'\"'+(MCFILT[field]===t?' selected':'')+'>'+esc(t)+'</option>'; }).join('')+\n      '<option value=\"'+esc(MCBLANK)+'\"'+(MCFILT[field]===MCBLANK?' selected':'')+'>(blank)</option></select>';\n  }\n  function ftext(field){ return '<input class=\"fx\" value=\"'+esc(MCFILT[field])+'\" oninput=\"mcSetFilter(\\''+field+'\\',this.value)\">'; }\n  var handlerFilterCell;\n  if(all){\n    handlerFilterCell='<button class=\"btn ghost sm\" onclick=\"mcHandlerPicker()\">'+(MCHSEL.length?('Handlers ('+MCHSEL.length+')'):'Filter…')+'</button>';\n  } else {\n    var oh=mcOtherHandlerList();\n    handlerFilterCell='<select class=\"fx\" onchange=\"mcSetFilter(\\'handler\\',this.value)\"><option value=\"\">All</option>'+\n      oh.map(function(h){ return '<option value=\"'+esc(h.email)+'\"'+(low(MCFILT.handler)===low(h.email)?' selected':'')+'>'+esc(h.name)+'</option>'; }).join('')+\n      '<option value=\"'+esc(MCBLANK)+'\"'+(MCFILT.handler===MCBLANK?' selected':'')+'>(blank — only me)</option></select>';\n  }\n  var rows=mcFiltered(), n=mcSelCount();\n  var active=MCFILT.name||MCFILT.tag||MCFILT.type||MCFILT.priority||MCFILT.area||MCFILT.sei||MCFILT.remarks||MCFILT.contacts||MCFILT.handler||MCHSEL.length;\n  var html='<div class=\"filterbar\">'+\n    '<span class=\"sub\">'+rows.length+' of '+d.total+'</span>'+\n    (canDel?'<button class=\"btn danger sm\" id=\"mcDel\" onclick=\"mcDelete()\"'+(n?'':' style=\"display:none\"')+'>Delete selected ('+n+')</button>':'')+\n    (active?'<button class=\"btn ghost sm\" onclick=\"mcClearFilters()\">Clear filters</button>':'')+\n    '</div>';\n  var hcol = all ? 'Handlers' : 'Other handlers';\n  html+='<div style=\"overflow-x:auto\"><table class=\"grid\">'+\n    '<tr>'+\n      (canDel?'<th style=\"width:24px\"><input type=\"checkbox\" '+(rows.length&&rows.every(function(c){return MCSEL[c.id];})?'checked':'')+' onclick=\"mcSelectAll(this.checked)\"></th>':'')+\n      '<th>Name</th><th>Location</th><th>Type</th><th>Priority</th><th>Area</th><th>SEI</th><th>Remarks</th><th>Contacts</th><th>'+hcol+'</th><th></th>'+\n    '</tr>'+\n    '<tr class=\"fr\">'+\n      (canDel?'<th></th>':'')+\n      '<th>'+ftext('name')+'</th><th>'+fsel('tag',d.tags)+'</th><th>'+fsel('type',d.types)+'</th><th>'+fsel('priority',d.priorities)+'</th>'+\n      '<th>'+ftext('area')+'</th><th>'+ftext('sei')+'</th><th>'+ftext('remarks')+'</th>'+\n      '<th><select class=\"fx\" onchange=\"mcSetFilter(\\'contacts\\',this.value)\"><option value=\"\">All</option><option value=\"0\"'+(MCFILT.contacts==='0'?' selected':'')+'>0 only</option><option value=\"1\"'+(MCFILT.contacts==='1'?' selected':'')+'>has some</option></select></th>'+\n      '<th>'+handlerFilterCell+'</th><th></th>'+\n    '</tr>';\n  rows.forEach(function(c){\n    var handlersTxt = all ? ((c.handlers||[]).map(function(h){ return h.name; }).join(', ')||'—')\n                          : (otherHandlers(c).length ? otherHandlers(c).map(function(h){ return h.name; }).join(', ') : '—');\n    var noC = (c.contacts||0)===0;\n    html+='<tr'+(noC?' class=\"nc\"':'')+'>'+\n      (canDel?'<td><input type=\"checkbox\" '+(MCSEL[c.id]?'checked':'')+' onclick=\"mcSel('+jsArg(c.id)+',this.checked)\"></td>':'')+\n      '<td><input class=\"ce\" value=\"'+esc(c.name)+'\" onchange=\"cellSave('+jsArg(c.id)+',\\'name\\',this.value,this)\"></td>'+\n      '<td>'+tagChips(c.tags)+'</td>'+\n      '<td>'+(canCls?'<select class=\"ce\" onchange=\"cellSave('+jsArg(c.id)+',\\'type\\',this.value,this)\">'+eopts(d.types,c.type)+'</select>':(typeChip(c.type)||'<span class=\"sub\">—</span>'))+'</td>'+\n      '<td>'+(canPri?'<select class=\"ce\" onchange=\"cellSave('+jsArg(c.id)+',\\'priority\\',this.value,this)\">'+eopts(d.priorities,c.priority)+'</select>':(priChip(c.priority)||'<span class=\"sub\">—</span>'))+'</td>'+\n      '<td><input class=\"ce\" value=\"'+esc(c.area||'')+'\" onchange=\"cellSave('+jsArg(c.id)+',\\'area\\',this.value,this)\"></td>'+\n      '<td>'+seiSelectHTML('', 'ce', c.sei, ' onchange=\"cellSaveMulti('+jsArg(c.id)+',\\'sei\\',this)\"')+'</td>'+\n      '<td><input class=\"ce\" value=\"'+esc(c.remarks||'')+'\" onchange=\"cellSave('+jsArg(c.id)+',\\'remarks\\',this.value,this)\"></td>'+\n      '<td>'+(noC?'<span class=\"pill red\">0</span>':'<span class=\"sub\">'+c.contacts+'</span>')+'</td>'+\n      '<td class=\"sub\">'+esc(handlersTxt)+'</td>'+\n      '<td style=\"white-space:nowrap\"><button class=\"btn lk\" onclick=\"nav(\\'customer\\','+jsArg(c.id)+')\">open</button> · <button class=\"btn lk\" onclick=\"newCaseFor('+jsArg(c.id)+')\">+ case</button></td>'+\n    '</tr>';\n  });\n  if(!rows.length) html+='<tr><td colspan=\"12\" class=\"empty\">No customers match these filters.</td></tr>';\n  html+='</table></div>';\n  setHtml('mcWrap', html);\n}\nfunction mcHandlerPicker(){\n  var list=allHandlerObjs();\n  var body='<p class=\"hint\" style=\"margin-top:0\">Show only customers handled by <b>all</b> the people you tick (find jointly-handled accounts).</p>'+\n    '<div id=\"hpick\" style=\"max-height:340px;overflow:auto;display:grid;gap:2px\">'+\n    list.map(function(h){ return '<label style=\"display:flex;gap:8px;align-items:center;padding:5px 7px;border:1px solid var(--line);border-radius:6px\"><input type=\"checkbox\" value=\"'+esc(h.email)+'\"'+(MCHSEL.indexOf(low(h.email))>-1?' checked':'')+'> '+esc(h.name)+'</label>'; }).join('')+\n    '</div>';\n  openModal('Filter by handlers', body,\n    '<button class=\"btn ghost\" onclick=\"MCHSEL=[];closeModal();renderMyCustomers()\">Clear</button>'+\n    '<button class=\"btn\" onclick=\"applyHandlerPicker()\">Apply</button>');\n}\nfunction applyHandlerPicker(){\n  var sel=[]; var box=el('hpick');\n  if(box) box.querySelectorAll('input:checked').forEach(function(x){ sel.push(low(x.value)); });\n  MCHSEL=sel; closeModal(); renderMyCustomers();\n}\nfunction newCaseFor(id){ mNewCase(id); }\nfunction mcSetFilter(k,val){ MCFILT[k]=val; renderMyCustomers(); }\nfunction mcClearFilters(){ MCFILT={name:'',tag:'',type:'',priority:'',area:'',sei:'',remarks:'',contacts:'',handler:''}; MCHSEL=[]; renderMyCustomers(); }\nfunction mcSel(id,on){ MCSEL[id]=on; var b=el('mcDel'); if(b){ var n=mcSelCount(); b.textContent='Delete selected ('+n+')'; b.style.display=n?'':'none'; } }\nfunction mcSelectAll(on){ mcFiltered().forEach(function(c){ MCSEL[c.id]=on; }); renderMyCustomers(); }\nfunction mcDelete(){\n  var ids=Object.keys(MCSEL).filter(function(id){ return MCSEL[id]; });\n  if(!ids.length) return;\n  S._delIds=ids;\n  openModal('Delete '+ids.length+' customer'+(ids.length>1?'s':''),\n    '<p>Move '+ids.length+' selected customer'+(ids.length>1?'s':'')+' to the recycle bin? Any with cases or quotations are skipped to protect linked work. An admin can restore them from Admin → Recycle bin.</p>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn danger\" onclick=\"mcDelete2()\">Move to recycle bin</button>');\n}\nfunction mcDelete2(){\n  gs('api_deleteCustomers', S._delIds).then(function(r){\n    closeModal();\n    toast(r.deleted+' moved to recycle bin'+(r.skipped.length?', '+r.skipped.length+' skipped':'')+'.');\n    if(r.skipped.length) toast(r.skipped.map(function(x){ return x.name+': '+x.reason; }).join(' · '), true);\n    loadGrid(true);\n  }).catch(oops);\n}\n\n/* Optimistic editing: the value lands in the UI immediately and the write is\n   batched and sent in the background. Only a failure interrupts the user. */\nvar PENDING={}, PREV={}, NODES={}, pendTimer=null;\nfunction cellSave(id, field, value, node){\n  var c = MC && MC.customers.filter(function(x){return x.id===id;})[0];\n  if(c){\n    PREV[id]=PREV[id]||{};\n    if(!(field in PREV[id])) PREV[id][field]=c[field];\n    c[field]=value;                                    // local model updated instantly\n  }\n  PENDING[id]=PENDING[id]||{}; PENDING[id][field]=value;\n  /* (see cellSaveMulti below for the array-valued <select multiple> path) */\n  NODES[id+'|'+field]=node;\n  node.style.outline='2px solid var(--line)';          // quiet \"not saved yet\"\n  clearTimeout(pendTimer);\n  pendTimer=setTimeout(flushCells, 700);\n}\n/* P8: SEI is now an array field edited through a <select multiple>, so the\n   grid needs a save path that sends every selected value, including none. */\nfunction cellSaveMulti(id, field, node){\n  cellSave(id, field, seiSelectedValues(node), node);\n}\n/* Rolls a failed optimistic edit back into whatever control produced it. */\nfunction setCellValue(node, val){\n  if(!node) return;\n  if(node.multiple){\n    var list = seiList(val);\n    [].slice.call(node.options||[]).forEach(function(o){ o.selected = list.indexOf(o.value)>-1; });\n    return;\n  }\n  if('value' in node) node.value = val;\n}\nfunction flushCells(){\n  var ids=Object.keys(PENDING);\n  if(!ids.length) return;\n  var patches=ids.map(function(id){ return {id:id, fields:PENDING[id]}; });\n  var sent=PENDING, sentNodes=NODES, sentPrev=PREV;\n  PENDING={}; NODES={}; PREV={};\n  gs('api_saveCustomerCells', patches).then(function(r){\n    (r.saved||[]).forEach(function(id){\n      Object.keys(sent[id]||{}).forEach(function(f){\n        var n=sentNodes[id+'|'+f]; if(!n) return;\n        n.style.outline='2px solid var(--brand)';\n        setTimeout(function(){ n.style.outline=''; },600);\n      });\n    });\n    (r.failed||[]).forEach(function(f){\n      var id=f.id;\n      Object.keys(sent[id]||{}).forEach(function(fld){\n        var n=sentNodes[id+'|'+fld];\n        if(n){ n.style.outline='2px solid var(--red)'; if(sentPrev[id] && fld in sentPrev[id]) setCellValue(n, sentPrev[id][fld]); }\n        var c=MC && MC.customers.filter(function(x){return x.id===id;})[0];\n        if(c && sentPrev[id] && fld in sentPrev[id]) c[fld]=sentPrev[id][fld];\n      });\n      toast(f.error||'Could not save that change.', true);\n    });\n    CACHE.customers=MC; CACHE.customersAt=Date.now();\n  }).catch(function(e){\n    Object.keys(sent).forEach(function(id){\n      Object.keys(sent[id]).forEach(function(fld){\n        var n=sentNodes[id+'|'+fld];\n        if(n){ n.style.outline='2px solid var(--red)'; if(sentPrev[id] && fld in sentPrev[id]) setCellValue(n, sentPrev[id][fld]); }\n        var c=MC && MC.customers.filter(function(x){return x.id===id;})[0];\n        if(c && sentPrev[id] && fld in sentPrev[id]) c[fld]=sentPrev[id][fld];\n      });\n    });\n    oops(e);\n  });\n}\nwindow.addEventListener('beforeunload', function(ev){\n  if(Object.keys(PENDING).length){ flushCells(); ev.preventDefault(); ev.returnValue=''; }\n});\n\nfunction mRestricted(id){\n  gs('api_getCustomer', id).then(function(d){\n    var hs = (d.handlers||[]).map(function(h){ return esc(h.name); }).join(', ') || '—';\n    openModal(d.customer.name,\n      '<div class=\"kv\"><b>Customer ID</b><span class=\"mono\">'+esc(d.customer.id)+'</span>'+\n      '<b>Location</b><span>'+tagChips(d.customer.tags)+'</span>'+\n      '<b>Type / Priority</b><span>'+(typeChip(d.customer.type)||'—')+' '+(priChip(d.customer.priority)||'')+'</span>'+\n      '<b>Handlers</b><span>'+hs+'</span></div>'+\n      '<p class=\"hint\" style=\"margin-top:14px\">This customer is in your area, but you are not one of its account handlers, so its contacts, cases and quotations are not open to you. Ask one of the handlers above (or an L3+ user) to add you as a handler.</p>',\n      '<button class=\"btn ghost\" onclick=\"closeModal()\">Close</button>');\n  }).catch(oops);\n}\n\n/* ---------------- new / edit customer ---------------- */\nfunction classFieldsHTML(c){\n  c = c||{};\n  return '<div class=\"frow\"><div><label>Type</label><select id=\"f_type\"><option value=\"\">—</option>'+selOptions(S.settings.types, c.type)+'</select></div>'+\n    '<div><label>Priority</label><select id=\"f_priority\"><option value=\"\">—</option>'+selOptions(S.settings.priorities, c.priority)+'</select></div></div>';\n}\nfunction priorityFieldHTML(c){\n  c = c||{};\n  return '<div class=\"frow\"><div><label>Priority</label><select id=\"f_priority\"><option value=\"\">—</option>'+selOptions(S.settings.priorities, c.priority)+'</select></div></div>';\n}\n/* P7: Location is mandatory and sits directly under the customer name.\n   The DB/RPC field is still `tags` - only the label changed. */\nfunction locationFieldHTML(sel){\n  return '<label class=\"req\">Location</label>'+\n    tagPickerHTML('f_tags', S.settings.tags, sel||[], false)+\n    '<p class=\"hint\">Controls who can see this customer. Pick at least one.</p>';\n}\n/* `afterName` is injected between the name row and everything else so the\n   location picker can be the second thing on the form. */\nfunction custFormHTML(c, afterName){\n  c = c||{};\n  return '<div class=\"frow\"><div><label class=\"req\">Customer name</label><input id=\"f_name\" value=\"'+esc(c.name||'')+'\"></div></div>'+\n    (afterName||'')+\n    '<div class=\"frow\"><div><label>Area</label><input id=\"f_area\" value=\"'+esc(c.area||'')+'\"></div>'+\n    '<div><label>GSTIN</label><input id=\"f_gstin\" value=\"'+esc(c.gstin||'')+'\"></div>'+\n    '<div><label>SEI</label>'+seiFieldHTML(c.sei)+'</div></div>'+\n    '<div class=\"frow\"><div><label>Address</label><input id=\"f_address\" value=\"'+esc(c.address||'')+'\"></div></div>'+\n    '<div class=\"frow\"><div><label>Website</label><input id=\"f_website\" value=\"'+esc(c.website||'')+'\"></div></div>'+\n    '<div class=\"frow\"><div><label>Notes</label><textarea id=\"f_notes\">'+esc(c.notes||'')+'</textarea></div></div>'+\n    '<div class=\"frow\"><div><label>Remarks</label><textarea id=\"f_remarks\">'+esc(c.remarks||'')+'</textarea></div></div>';\n}\nfunction mNewCustomer(prefillName){\n  var body = custFormHTML({ name: prefillName || '' }, locationFieldHTML([])) + classFieldsHTML({}) +\n    '<div class=\"card\" style=\"margin-top:16px;padding:14px;background:#FAFBFA\"><div class=\"ovl\" style=\"margin-bottom:10px\">First contact (optional)</div>'+\n    '<div class=\"frow\"><div><label>Name</label><input id=\"fc_name\"></div><div><label>Designation</label><input id=\"fc_desig\"></div></div>'+\n    '<div class=\"frow\"><div><label>Phone</label><input id=\"fc_phone\"></div><div><label>Email</label><input id=\"fc_email\"></div></div></div>';\n  openModal('New customer', body,\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn\" id=\"saveCustBtn\" onclick=\"saveNewCustomer(false)\">Save customer</button>', true);\n  el('f_name').focus();\n}\nfunction saveNewCustomer(force){\n  var d = {\n    name:v('f_name'), area:v('f_area'), sei:seiVal('f_sei'), remarks:v('f_remarks'),\n    gstin:v('f_gstin'), address:v('f_address'), website:v('f_website'), notes:v('f_notes'),\n    type:v('f_type'), priority:v('f_priority'), tags: pickerVal('f_tags'), force: !!force,\n    contact:{ name:v('fc_name'), designation:v('fc_desig'), phone:v('fc_phone'), email:v('fc_email') }\n  };\n  if(!d.name){ toast('Customer name is required.', true); return; }\n  /* P7: mirrors the server's mandatory-location rule so the user is told\n     before the round trip. */\n  if(!d.tags.length){ toast('Location is required — pick at least one.', true); return; }\n  el('saveCustBtn').disabled = true;\n  gs('api_createCustomer', d).then(function(r){\n    closeModal(); toast('Customer created — '+r.id); nav('customer', r.id);\n  }).catch(function(e){\n    el('saveCustBtn').disabled = false;\n    var m = errMsg(e);\n    if(m.indexOf('DUPLICATE:')===0){\n      setText('saveCustBtn', 'Create anyway');\n      el('saveCustBtn').onclick = function(){ saveNewCustomer(true); };\n      toast(m.replace('DUPLICATE:','').trim(), true);\n    }else oops(e);\n  });\n}\nfunction mEditCustomer(c){\n  var canCls = CUR.customer && CUR.customer.canEditTags;       // L3+: tags, type, archive\n  var canPri = (CUR.customer && CUR.customer.canEditPriority) || lvl()>=2;  // L2+: priority\n  var body = custFormHTML(c, canCls ? locationFieldHTML(c.tags||[]) : '');\n  if(canCls){\n    body += classFieldsHTML(c);\n    body += '<div class=\"frow\" style=\"margin-top:12px\"><div><label>Status</label><select id=\"f_status\">'+\n      '<option'+(c.status!=='Archived'?' selected':'')+'>Active</option>'+\n      '<option'+(c.status==='Archived'?' selected':'')+'>Archived</option></select></div></div>';\n  }else if(canPri){\n    body += priorityFieldHTML(c);\n    body += '<p class=\"hint\">Location, type and archive status can only be changed at L3 or higher.</p>';\n  }else{\n    body += '<p class=\"hint\">Location, type, priority and archive status can only be changed at L2 or higher.</p>';\n  }\n  openModal('Edit — '+c.name, body,\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn\" id=\"saveBtn\" onclick=\"saveEditCustomer('+jsArg(c.id)+')\">Save changes</button>', true);\n}\nfunction saveEditCustomer(id){\n  var canCls = CUR.customer && CUR.customer.canEditTags;\n  var canPri = (CUR.customer && CUR.customer.canEditPriority) || lvl()>=2;\n  var d = {\n    name:v('f_name'), area:v('f_area'), sei:seiVal('f_sei'), remarks:v('f_remarks'),\n    gstin:v('f_gstin'), address:v('f_address'), website:v('f_website'), notes:v('f_notes')\n  };\n  if(canCls){\n    d.tags = pickerVal('f_tags'); d.type = v('f_type'); d.status = v('f_status');\n    /* P7: an edit may never leave a customer with no location. */\n    if(!d.tags.length){ toast('Location is required — pick at least one.', true); return; }\n  }\n  if(canPri && el('f_priority')){ d.priority = v('f_priority'); }\n  el('saveBtn').disabled = true;\n  gs('api_updateCustomer', id, d).then(function(){ closeModal(); toast('Saved.'); vCustomer(id); })\n    .catch(function(e){ el('saveBtn').disabled=false; oops(e); });\n}\n\n/* parseBulkRows: shared paste-row parser. The customer-bulk-add UI that used\n   to call it is gone, but the contacts bulk-add tool (mBulkContacts, bk_paste\n   below) still depends on it - keep it. */\nfunction parseBulkRows(raw){\n  return raw.split(/\\r?\\n/).map(function(l){ return l.replace(/ /g,' '); })\n    .filter(function(l){ return l.trim()!==''; })\n    .map(function(l){\n      var parts = l.indexOf('\\t')>-1 ? l.split('\\t') : l.split(',');\n      return parts.map(function(p){ return p.trim(); });\n    });\n}\n\n/* =====================================================================\n * CUSTOMER DETAIL\n * =================================================================== */\nvar CUR = {};\nfunction vCustomer(id){\n  S.route='customer'; setRouteAttr('customer'); S.routeArg=id; setTab('customers');\n  var hit=CACHE.cust[id];\n  if(hit){ renderCustomer(hit.d); if(fresh(hit.at)) return; }\n  else setHtml('main', '<div class=\"sub\">Loading customer…</div>');\n  gs('api_getCustomer', id).then(function(d){\n    CACHE.cust[id]={d:d, at:Date.now()};\n    if(S.route!=='customer' || S.routeArg!==id) return;\n    if(hit && sameData(hit.d,d)) return;\n    renderCustomer(d);\n  }).catch(function(e){ if(hit) return; setHtml('main', '<div class=\"card\"><div class=\"empty\">'+esc(errMsg(e))+'<div style=\"margin-top:12px\"><button class=\"btn ghost\" onclick=\"nav(S.route,S.routeArg)\">Retry</button></div></div></div>'); });\n}\nfunction renderCustomer(d){\n    if(d.access!=='FULL'){ var _rid=d.customer&&d.customer.id; vCustomers(); if(_rid) mRestricted(_rid); return; }\n    CUR.customer = d;\n    var c = d.customer;\n    var html = '<div class=\"pagehead\"><div class=\"grow\">'+\n      '<div class=\"crumb\"><a onclick=\"nav(\\'customers\\')\">Customers</a> / <span class=\"mono\">'+esc(c.id)+'</span></div>'+\n      '<h1>'+esc(c.name)+'</h1><div style=\"margin-top:6px\">'+tagChips(c.tags)+' '+typeChip(c.type)+' '+priChip(c.priority)+\n      (c.status==='Archived'?' <span class=\"badge b-red\">Archived</span>':'')+'</div></div>'+\n      '<button class=\"btn ghost\" onclick=\"mEditCustomer(CUR.customer.customer)\">Edit</button>'+\n      '<button class=\"btn\" onclick=\"mNewCase('+jsArg(c.id)+')\">+ Case</button>'+\n      '<button class=\"btn ghost\" onclick=\"openBuilderForCustomer()\">+ Quotation</button>'+\n      '<button class=\"btn ghost\" onclick=\"mUploadQuote()\">Upload quotation</button></div>';\n\n    html += '<div class=\"row\"><div class=\"col\">';\n    html += '<div class=\"card\"><div class=\"ovl\">Details</div><div class=\"kv\">'+\n      '<b>Type / Priority</b><span>'+(typeChip(c.type)||'—')+' '+(priChip(c.priority)||'')+'</span>'+\n      '<b>Area</b><span>'+esc(c.area||'—')+'</span>'+\n      '<b>SEI</b><span>'+esc(seiList(c.sei).join(', ')||'—')+'</span>'+\n      '<b>Remarks</b><span>'+esc(c.remarks||'—')+'</span>'+\n      '<b>Address</b><span>'+esc(c.address||'—')+'</span>'+\n      '<b>GSTIN</b><span class=\"mono\">'+esc(c.gstin||'—')+'</span>'+\n      '<b>Website</b><span>'+(c.website?'<a href=\"'+esc(c.website)+'\" target=\"_blank\" rel=\"noopener\">'+esc(c.website)+'</a>':'—')+'</span>'+\n      '<b>Notes</b><span>'+esc(c.notes||'—')+'</span>'+\n      '<b>Created</b><span class=\"sub\">'+esc(c.createdOn)+' by '+esc(c.createdBy)+'</span></div></div>';\n\n    html += '<div class=\"card\"><div class=\"ovl\">Account handlers</div>';\n    (d.handlers||[]).forEach(function(h){\n      /* P9: Direct is a virtual, login-less placeholder that the server clears\n         automatically the moment a real handler is added. Offering Remove\n         could only ever leave the customer with no handler at all, so it gets\n         no Remove button and no (non-existent) email address. */\n      var direct = isDirectAccount(h.email);\n      html += '<div class=\"qr\"><div style=\"flex:1\"><b>'+esc(h.name)+'</b>'+\n        (direct\n          ? '<div class=\"sub\">Unassigned — no account handler yet. Adding one replaces this automatically.</div>'\n          : '<div class=\"sub mono\">'+esc(h.email)+'</div>')+'</div>'+\n        (direct ? '' : '<button class=\"btn danger sm\" onclick=\"rmHandler('+jsArg(c.id)+','+jsArg(h.email)+')\">Remove</button>')+\n        '</div>';\n    });\n    if(!(d.handlers||[]).length) html += '<div class=\"empty\">No handlers assigned.</div>';\n    html += '<button class=\"btn ghost sm\" onclick=\"mAddHandler('+jsArg(c.id)+')\">+ Add handler</button></div>';\n    html += '</div><div class=\"col\" style=\"flex:1.4\">';\n\n    html += '<div class=\"card\"><div class=\"ovl\">Contacts</div>';\n    if(!(d.contacts||[]).length) html += '<div class=\"empty\">No contacts yet.</div>';\n    (d.contacts||[]).forEach(function(ct){\n      html += '<div class=\"qr\"><div style=\"flex:1;min-width:170px\"><b>'+esc(ct.name)+'</b>'+\n        (ct.designation?' <span class=\"sub\">· '+esc(ct.designation)+'</span>':'')+\n        '<div class=\"sub mono\">'+esc([ct.phone,ct.email].filter(Boolean).join('  ·  ')||'—')+'</div>'+\n        (ct.notes?'<div class=\"sub\">'+esc(ct.notes)+'</div>':'')+'</div>'+\n        '<button class=\"btn ghost sm\" onclick=\"mContact('+jsArg(c.id)+','+jsJsonArg(ct)+')\">Edit</button>'+\n        '<button class=\"btn danger sm\" onclick=\"delContact('+jsArg(ct.id)+','+jsArg(c.id)+')\">Delete</button></div>';\n    });\n    html += '<div style=\"display:flex;gap:8px;flex-wrap:wrap\"><button class=\"btn ghost sm\" onclick=\"mContact('+jsArg(c.id)+',null)\">+ Add contact</button>'+\n      '<button class=\"btn ghost sm\" onclick=\"mBulkContacts('+jsArg(c.id)+')\">Bulk add contacts</button></div></div>';\n    html += '</div></div>';\n\n    html += '<div class=\"card\"><div class=\"ovl\">Cases</div>';\n    if(!(d.cases||[]).length) html += '<div class=\"empty\">No cases yet — create one, or it will be created automatically with the first quotation.</div>';\n    else{\n      html += '<table><tr><th>ID</th><th>Title</th><th>Status</th><th>Priority</th><th class=\"tnum-r\">Value</th><th>Owners</th><th>Assigned to</th><th class=\"tnum-r\">Quotes</th><th>Updated</th></tr>';\n      d.cases.forEach(function(o){\n        var val = o.outcome==='Won' ? o.orderValue : '';\n        html += '<tr class=\"clk\" onclick=\"nav(\\'case\\','+jsArg(o.id)+')\">'+\n          '<td class=\"mono\">'+esc(o.id)+'</td><td><b>'+esc(o.title)+'</b></td>'+\n          '<td>'+caseStatusChip(o.stage,o.outcome)+'</td><td>'+(priChip(o.priority)||'<span class=\"sub\">—</span>')+'</td>'+\n          '<td class=\"tnum-r\">'+caseValueCell(o)+'</td>'+\n          '<td class=\"sub\">'+esc((o.owners||[]).join(', ')||'—')+'</td>'+\n          '<td class=\"sub\">'+(o.outcome ? '—' : esc(o.assignee||'—'))+'</td>'+\n          '<td class=\"tnum-r mono\">'+esc(o.quotes)+'</td>'+\n          '<td class=\"sub mono\">'+esc(o.updatedOn)+'</td></tr>';\n      });\n      html += '</table>';\n    }\n    html += '</div>';\n\n    html += '<div class=\"card\"><div class=\"ovl\">Quotations (latest revision per number)</div>';\n    if(!(d.quotes||[]).length) html += '<div class=\"empty\">No quotations yet.</div>';\n    else{\n      html += '<table><tr><th>Quote no.</th><th>Title</th><th class=\"tnum-r\">Total</th><th>Status</th><th>Date</th><th></th></tr>';\n      d.quotes.forEach(function(q){\n        html += '<tr class=\"clk\" onclick=\"mQuoteViewer('+jsArg(q.quoteNo)+','+q.rev+')\">'+\n          '<td class=\"mono\">'+esc(q.quoteNo)+' R'+q.rev+'</td><td>'+esc(q.title)+'</td>'+\n          '<td class=\"tnum-r\">'+moneyCell(q.currency,q.total)+'</td><td>'+qStatusChip(q.status)+'</td>'+\n          '<td class=\"sub mono\">'+esc(q.date)+'</td>'+\n          '<td>'+(q.pdf?'<a href=\"'+esc(q.pdf)+'\" target=\"_blank\" rel=\"noopener\" onclick=\"event.stopPropagation()\">PDF</a>':'')+'</td></tr>';\n      });\n      html += '</table>';\n    }\n    html += '</div>';\n    setHtml('main', html);\n}\nfunction openBuilderForCustomer(){\n  var d = CUR.customer;\n  var cases = (d.cases||[]).filter(function(o){ return o.outcome!=='Won' && o.outcome!=='Lost'; })\n    .map(function(o){ return {id:o.id, title:o.title}; });\n  mQuoteBuilder({ customerId:d.customer.id, customerName:d.customer.name, cases:cases });\n}\n\n/* ---------------- handlers & contacts ---------------- */\nfunction mAddHandler(custId){\n  openModal('Add account handler',\n    '<label class=\"req\">Username</label><div style=\"display:flex;align-items:center;gap:6px\"><input id=\"f_hmail\" style=\"flex:1\"><span class=\"mono sub\">@'+esc(S.settings.domain)+'</span></div>'+\n    '<p class=\"hint\">Enter just the username. They must already be an active CRM user (Admin → Users). Handlers get full access to this customer.</p>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn\" onclick=\"addHandler('+jsArg(custId)+')\">Add</button>');\n  el('f_hmail').focus();\n}\nfunction addHandler(custId){\n  gs('api_addHandler', custId, v('f_hmail')).then(function(){ closeModal(); toast('Handler added.'); vCustomer(custId); }).catch(oops);\n}\nfunction rmHandler(custId, email){\n  openModal('Remove handler','<p>Remove <b>'+esc(email)+'</b> as a handler for this customer? They may lose access to its details.</p>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn danger\" onclick=\"rmHandler2('+jsArg(custId)+','+jsArg(email)+')\">Remove</button>');\n}\nfunction rmHandler2(custId,email){\n  gs('api_removeHandler', custId, email).then(function(){ closeModal(); toast('Handler removed.'); vCustomer(custId); }).catch(oops);\n}\nfunction mContact(custId, ct){\n  ct = ct||{};\n  openModal(ct.id?'Edit contact':'Add contact',\n    '<div class=\"frow\"><div><label class=\"req\">Name</label><input id=\"fc_name\" value=\"'+esc(ct.name||'')+'\"></div>'+\n    '<div><label>Designation</label><input id=\"fc_desig\" value=\"'+esc(ct.designation||'')+'\"></div></div>'+\n    '<div class=\"frow\"><div><label>Phone</label><input id=\"fc_phone\" value=\"'+esc(ct.phone||'')+'\"></div>'+\n    '<div><label>Email</label><input id=\"fc_email\" value=\"'+esc(ct.email||'')+'\"></div></div>'+\n    '<div class=\"frow\"><div><label>Notes</label><input id=\"fc_notes\" value=\"'+esc(ct.notes||'')+'\"></div></div>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn\" onclick=\"saveContact('+jsArg(custId)+','+jsArg(ct.id||'')+')\">Save</button>');\n  el('fc_name').focus();\n}\nfunction saveContact(custId, ctId){\n  var d = {name:v('fc_name'), designation:v('fc_desig'), phone:v('fc_phone'), email:v('fc_email'), notes:v('fc_notes')};\n  if(!d.name){ toast('Contact name is required.', true); return; }\n  var p = ctId ? gs('api_updateContact', ctId, d) : gs('api_addContact', custId, d);\n  p.then(function(){ closeModal(); toast('Contact saved.'); vCustomer(custId); }).catch(oops);\n}\nfunction delContact(ctId, custId){\n  openModal('Delete contact','<p>Delete this contact? This cannot be undone.</p>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn danger\" onclick=\"delContact2('+jsArg(ctId)+','+jsArg(custId)+')\">Delete</button>');\n}\nfunction delContact2(ctId,custId){\n  gs('api_deleteContact', ctId).then(function(){ closeModal(); toast('Contact deleted.'); vCustomer(custId); }).catch(oops);\n}\nfunction mBulkContacts(custId){\n  openModal('Bulk add contacts',\n    '<p class=\"sub\" style=\"margin-bottom:8px\">Paste one contact per line. Columns, in order:</p>'+\n    '<p class=\"mono\" style=\"font-size:12px;background:#FAFBFA;border:1px solid var(--line);border-radius:7px;padding:9px\">Name · Designation · Phone · Email</p>'+\n    '<p class=\"hint\">Only Name is required. Tab- or comma-separated.</p>'+\n    '<textarea id=\"bk_paste\" style=\"min-height:130px;margin-top:10px;font-family:var(--mono);font-size:12px\"></textarea>'+\n    '<div style=\"margin-top:8px\"><button class=\"btn sm\" onclick=\"previewBulkContacts()\">Preview</button></div>'+\n    '<div id=\"bk_prev\" style=\"margin-top:10px\"></div>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn\" id=\"bk_save\" style=\"display:none\" onclick=\"saveBulkContacts('+jsArg(custId)+')\">Add contacts</button>', true);\n  el('bk_paste').focus();\n}\nvar BKROWS = [];\nfunction previewBulkContacts(){\n  var rows = parseBulkRows(el('bk_paste').value);\n  BKROWS = rows.map(function(r){ return { name:r[0]||'', designation:r[1]||'', phone:r[2]||'', email:r[3]||'' }; })\n    .filter(function(r){ return r.name; });\n  if(!BKROWS.length){ toast('No valid rows (every row needs a name).', true); setHtml('bk_prev', ''); el('bk_save').style.display='none'; return; }\n  var html = '<div class=\"ovl\">Preview — '+BKROWS.length+' contact'+(BKROWS.length===1?'':'s')+'</div><table><tr><th>Name</th><th>Designation</th><th>Phone</th><th>Email</th></tr>';\n  BKROWS.slice(0,10).forEach(function(r){ html += '<tr><td><b>'+esc(r.name)+'</b></td><td>'+esc(r.designation||'—')+'</td><td class=\"mono\">'+esc(r.phone||'—')+'</td><td>'+esc(r.email||'—')+'</td></tr>'; });\n  html += '</table>'+(BKROWS.length>10?'<div class=\"hint\">…and '+(BKROWS.length-10)+' more.</div>':'');\n  setHtml('bk_prev', html); el('bk_save').style.display='';\n}\nfunction saveBulkContacts(custId){\n  if(!BKROWS.length){ toast('Nothing to add.', true); return; }\n  el('bk_save').disabled = true;\n  gs('api_bulkContacts', custId, BKROWS).then(function(r){ closeModal(); toast(r.created+' contacts added.'); vCustomer(custId); })\n    .catch(function(e){ el('bk_save').disabled=false; oops(e); });\n}\n\n/* =====================================================================\n * CASES\n * =================================================================== */\nvar NEWCASE = { kind:'Lead' };\nfunction mNewCase(custId){\n  NEWCASE = { kind:'Lead' };\n  ensureUsers().then(function(){\n    var body =\n      '<div class=\"frow\"><div><label>What are you creating?</label><div class=\"seg\" id=\"fk_seg\">'+\n        '<button type=\"button\" class=\"on\" onclick=\"setCaseKind(\\'Lead\\')\">Lead</button>'+\n        '<button type=\"button\" onclick=\"setCaseKind(\\'Opportunity\\')\">Opportunity</button>'+\n        '<button type=\"button\" onclick=\"setCaseKind(\\'Order\\')\">Order (Won)</button></div></div></div>'+\n      '<div class=\"frow\"><div style=\"flex:2\"><label class=\"req\">Title</label><input id=\"fo_title\"></div></div>'+\n      '<div class=\"frow\"><div><label'+(lvl()>=5?' class=\"req\"':'')+'>Assign to</label>'+\n      (lvl()>=5\n        ? '<select id=\"fo_owner\"><option value=\"\">— choose who works this —</option>'+(S.users||[]).map(function(x){ return '<option value=\"'+esc(x.email)+'\">'+esc(x.name)+'</option>'; }).join('')+'</select>'\n        : userSelectHTML('fo_owner', S.user.email))+\n      '<div class=\"hint\">'+(lvl()>=5?'Pick a handler or search anyone — you can\\'t hold the ticket yourself.':'Whoever holds the ticket and works the case. The account handlers are the owners.')+'</div></div></div>'+\n      '<div class=\"frow\"><div><label>Priority</label><select id=\"fo_pri\">'+\n        '<option value=\"\">— none —</option>'+ selOptions(S.settings.priorities || ['High','Medium','Low'], '') +\n      '</select><div class=\"hint\">Optional. Leave as none if it is not urgent.</div></div></div>'+\n      '<div id=\"fo_orderwrap\" style=\"display:none\">'+\n        '<div class=\"card\" style=\"background:#FAFBFA;padding:14px\"><div class=\"ovl\">Order details</div>'+\n        '<div class=\"frow\"><div><label class=\"req\">Order value ('+esc(S.settings.currency)+')</label><input id=\"fo_orderval\" type=\"number\" min=\"0\"></div></div>'+\n        '<label class=\"req\">Product categories</label>'+ multiPickHTML('fo_cats', catPickItems(), []) +'</div></div>'+\n      '<div class=\"frow\"><div><label>Details</label><textarea id=\"fo_det\"></textarea></div></div>';\n    openModal('New case', body,\n      '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n      '<button class=\"btn\" id=\"caseSaveBtn\" onclick=\"saveNewCase('+jsArg(custId)+')\">Create</button>', true);\n    el('fo_title').focus();\n  }).catch(oops);\n}\n/* P10: the modal used to call EVERY non-removable owner an account handler.\n   On a Direct-handled customer that made the person who merely created the\n   case look like the account handler. The server now says why each person\n   owns the case, so say exactly that. */\nfunction ownerSourceLabel(o){\n  if(o.source==='handler') return '(account handler — owner of every case on the account)';\n  if(o.source==='creator') return '(created this case)';\n  if(o.source==='manual')  return '(added to this case)';\n  /* Pre-P10 payloads carry no source; fall back to the old removable split. */\n  return o.removable ? '(added to this case)' : '(account handler — owner of every case on the account)';\n}\nfunction mOwners(){\n  var d=CUR.caseData; if(!d) return;\n  ensureUsers().then(function(){\n    var list=d.case.ownerList||[];\n    var rowsH = list.map(function(o){\n      return '<div class=\"qr\"><div style=\"flex:1\">'+esc(o.name)+' <span class=\"sub\">'+esc(ownerSourceLabel(o))+'</span></div>'+\n        (o.removable?'<button class=\"btn lk\" onclick=\"removeOwner('+jsArg(o.email)+')\">remove</button>':'')+'</div>';\n    }).join('');\n    var body='<p class=\"hint\" style=\"margin-top:0\">Account handlers are always owners and can\\'t be removed here (remove them as a handler on the customer instead). You can add other users as owners of this case.</p>'+\n      rowsH+\n      '<div class=\"frow\" style=\"margin-top:12px\"><div><label>Add another owner</label>'+userSelectHTML('own_user','')+'</div>'+\n      '<div style=\"display:flex;align-items:flex-end\"><button class=\"btn\" onclick=\"addOwner()\">Add</button></div></div>';\n    openModal('Case owners', body, '<button class=\"btn ghost\" onclick=\"closeModal()\">Close</button>');\n  }).catch(oops);\n}\nfunction addOwner(){\n  var id=CUR.caseData.case.id;\n  gs('api_addCaseOwner', id, v('own_user')).then(function(){ closeModal(); toast('Owner added.'); vCase(id); }).catch(oops);\n}\nfunction removeOwner(email){\n  var id=CUR.caseData.case.id;\n  gs('api_removeCaseOwner', id, email).then(function(){ closeModal(); toast('Owner removed.'); vCase(id); }).catch(oops);\n}\nfunction setCaseKind(k){\n  NEWCASE.kind = k;\n  el('fk_seg').querySelectorAll('button').forEach(function(b){ b.className = (b.textContent.indexOf(k)===0 || (k==='Order'&&b.textContent.indexOf('Order')===0))?'on':''; });\n  el('fo_orderwrap').style.display = k==='Order' ? '' : 'none';\n}\nfunction saveNewCase(custId){\n  var kind = NEWCASE.kind;\n  var d = { title:v('fo_title'), details:v('fo_det'), assignee:v('fo_owner'), priority:v('fo_pri') };\n  if(!d.title){ toast('Give the case a short title.', true); return; }\n  if(lvl()>=5 && !d.assignee){ toast('Choose who this case is assigned to.', true); return; }\n  if(kind==='Order'){\n    d.order = true; d.orderValue = v('fo_orderval'); d.categories = pickerVal('fo_cats');\n    if(!(Number(d.orderValue)>0)){ toast('Enter the order value.', true); return; }\n    if(!d.categories.length){ toast('Select at least one product category.', true); return; }\n  }else{\n    d.stage = kind;\n  }\n  el('caseSaveBtn').disabled = true;\n  gs('api_createCase', custId, d).then(function(r){ closeModal(); toast('Case created — '+r.id); nav('case', r.id); })\n    .catch(function(e){ el('caseSaveBtn').disabled=false; oops(e); });\n}\n\n/* pick a customer, then create a case (used from the Cases page) */\nfunction mPickCustomerThenCase(){\n  openModal('New case — pick a customer',\n    '<label>Customer</label><input id=\"pc_q\" oninput=\"pcSearch()\">'+\n    '<div id=\"pc_res\" class=\"ql-res\" style=\"display:none\"></div>'+\n    '<p class=\"hint\" style=\"margin-top:10px\">Don\\'t see them? Add the customer first from the Customers tab, or use Quick log.</p>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>');\n  el('pc_q').focus();\n}\nvar pcT=null;\nfunction pcSearch(){ clearTimeout(pcT); pcT=setTimeout(pcRun,300); }\nfunction pcRun(){\n  var q=v('pc_q'); if(q.length<2){ el('pc_res').style.display='none'; return; }\n  gs('api_searchCustomers', q).then(function(list){\n    if(v('pc_q')!==q) return;\n    var full = list.filter(function(c){ return c.access==='FULL'; });\n    if(!full.length){ el('pc_res').style.display='block'; setHtml('pc_res', '<div class=\"empty\">No customers you can add a case to.</div>'); return; }\n    el('pc_res').style.display='block';\n    setHtml('pc_res', full.map(function(c){\n      return '<div class=\"qr\" onclick=\"closeModal();mNewCase('+jsArg(c.id)+')\"><div style=\"flex:1\"><b>'+esc(c.name)+'</b> '+tagChips(c.tags)+'</div></div>';\n    }).join(''));\n  }).catch(oops);\n}\n\nfunction vCase(id){\n  S.route='case'; setRouteAttr('case'); S.routeArg=id; setTab('cases');\n  var hit=CACHE.kase[id];\n  if(hit){ renderCase(hit.d); if(fresh(hit.at)) return; }\n  else setHtml('main', '<div class=\"sub\">Loading case…</div>');\n  gs('api_getCase', id).then(function(d){\n    CACHE.kase[id]={d:d, at:Date.now()};\n    if(S.route!=='case' || S.routeArg!==id) return;\n    if(hit && sameData(hit.d,d)) return;\n    renderCase(d);\n  }).catch(function(e){ if(hit) return; setHtml('main', '<div class=\"card\"><div class=\"empty\">'+esc(errMsg(e))+'<div style=\"margin-top:12px\"><button class=\"btn ghost\" onclick=\"nav(S.route,S.routeArg)\">Retry</button></div></div></div>'); });\n}\nfunction renderCase(d){\n    CUR.caseData = d;\n    var o = d.case;\n    var html = '<div class=\"pagehead\"><div class=\"grow\">'+\n      '<div class=\"crumb\"><a onclick=\"nav(\\'customers\\')\">Customers</a> / <a onclick=\"nav(\\'customer\\','+jsArg(d.customer.id)+')\">'+esc(d.customer.name)+'</a> / <span class=\"mono\">'+esc(o.id)+'</span></div>'+\n      '<h1>'+esc(o.title)+'</h1>'+\n      '<div class=\"sub\" style=\"margin-top:5px\">'+caseStatusChip(o.stage,o.outcome)+' '+priChip(o.priority)+\n      ' &nbsp; Owners: <b>'+esc((o.owners||[]).join(', ')||'—')+'</b>'+\n      (d.canEdit?' <button class=\"btn lk\" onclick=\"mOwners()\">manage</button>':'')+\n      (o.outcome ? '' :\n        ' &nbsp;·&nbsp; Assigned to: <b>'+esc(o.assignee||'nobody')+'</b>'+\n        (d.canAssignTicket?' <button class=\"btn lk\" onclick=\"mAssignCase()\">reassign</button>':''))+\n      '</div></div>';\n    if(d.canEdit) html += '<button class=\"btn ghost\" onclick=\"mEditCase(CUR.caseData.case)\">Edit</button>'+\n      '<button class=\"btn ghost\" onclick=\"openBuilderForCase()\">+ Quotation</button>'+\n      '<button class=\"btn ghost\" onclick=\"mUploadQuote()\">Upload quotation</button>';\n    html += '</div>';\n\n    if(d.latestHandoverNote) html += '<div class=\"card\" style=\"margin-bottom:12px\"><div class=\"ovl\">Latest handover note</div><div class=\"d\" style=\"white-space:pre-wrap\">'+esc(d.latestHandoverNote)+'</div>'+attachmentLinksHtml(latestNoteAttachments(d))+'</div>';\n\n    // status / stage controls\n    html += '<div class=\"card\"><div class=\"ovl\">Status</div>';\n    if(o.outcome==='Won'){\n      html += '<p style=\"margin-bottom:8px\">'+outcomeChip('Won')+' <b class=\"money\">'+esc(S.settings.currency)+' '+fmtMoney(o.orderValue)+'</b> — '+\n        (o.wonCategories||[]).map(function(c){ return '<span class=\"chip\">'+esc(c)+'</span>'; }).join('')+\n        (o.closedOn?' <span class=\"sub mono\">· '+esc(o.closedOn)+'</span>':'')+'</p>';\n    }else if(o.outcome==='Lost'){\n      html += '<p style=\"margin-bottom:8px\">'+outcomeChip('Lost')+(o.outcomeNote?' <span class=\"sub\">— '+esc(o.outcomeNote)+'</span>':'')+(o.closedOn?' <span class=\"sub mono\">· '+esc(o.closedOn)+'</span>':'')+'</p>';\n    }else if(o.outcome==='Hold'){\n      html += '<p style=\"margin-bottom:8px\">'+outcomeChip('Hold')+(o.outcomeNote?' <span class=\"sub\">— '+esc(o.outcomeNote)+'</span>':'')+' <span class=\"sub\">(stage kept at '+esc(o.stage)+')</span></p>';\n    }\n    if(d.canEdit){\n      if(o.outcome!=='Won' && o.outcome!=='Lost'){\n        html += '<div class=\"frow\" style=\"align-items:flex-end\"><div><label>Stage</label><select id=\"stSel\">'+\n          S.settings.stages.map(function(st){ return '<option'+(st===o.stage?' selected':'')+'>'+esc(st)+'</option>'; }).join('')+'</select></div>'+\n          '<div style=\"flex:2\"><label>Note (optional)</label><input id=\"stNote\"></div>'+\n          '<div style=\"flex:0\"><button class=\"btn\" onclick=\"doStage('+jsArg(o.id)+')\">Update stage</button></div></div>';\n      }\n      html += '<div class=\"frow\" style=\"align-items:flex-end\"><div><label>Priority</label><select id=\"priSel\">'+\n        '<option value=\"\">— none —</option>'+ selOptions(S.settings.priorities || ['High','Medium','Low'], o.priority||'') +\n        '</select></div><div style=\"flex:0\"><button class=\"btn\" onclick=\"doPriority('+jsArg(o.id)+')\">Update priority</button></div></div>';\n      html += '<div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:6px\">';\n      if(o.outcome!=='Won') html += '<button class=\"btn sm\" onclick=\"mWon('+jsArg(o.id)+')\">Mark Won</button>';\n      if(o.outcome!=='Lost') html += '<button class=\"btn danger sm\" onclick=\"mOutcomeNote('+jsArg(o.id)+',\\'Lost\\')\">Mark Lost</button>';\n      if(o.outcome!=='Hold') html += '<button class=\"btn ghost sm\" onclick=\"mOutcomeNote('+jsArg(o.id)+',\\'Hold\\')\">Put on Hold</button>';\n      if(o.outcome) html += '<button class=\"btn ghost sm\" onclick=\"reopenCase('+jsArg(o.id)+')\">Reopen</button>';\n      html += '</div>';\n    }\n    html += '</div>';\n\n    if(o.details){ html += '<div class=\"card\"><div class=\"ovl\">Details</div><div style=\"white-space:pre-wrap\">'+esc(o.details)+'</div></div>'; }\n\n    // quotations\n    html += '<div class=\"card\"><div class=\"ovl\">Quotations</div>';\n    if(!(d.quotes||[]).length) html += '<div class=\"empty\">No quotations yet for this case.</div>';\n    else{\n      var groups = {}, order = [];\n      d.quotes.forEach(function(q){ if(!groups[q.quoteNo]){ groups[q.quoteNo]=[]; order.push(q.quoteNo); } groups[q.quoteNo].push(q); });\n      order.forEach(function(no){\n        html += '<div style=\"margin-bottom:14px\"><div class=\"mono\" style=\"font-weight:600;margin-bottom:6px\">'+esc(no)+'</div>';\n        groups[no].forEach(function(q){\n          html += '<div class=\"qr\"><span class=\"mono\">R'+q.rev+'</span>'+qStatusChip(q.status)+\n            '<div style=\"flex:1;min-width:140px\">'+esc(q.title)+'<div class=\"sub mono\">'+esc(q.date)+' · '+esc(q.by)+'</div></div>'+\n            '<span class=\"money\">'+esc(q.currency)+' '+fmtMoney(q.total)+'</span>'+\n            (q.pdf?'<a href=\"'+esc(q.pdf)+'\" target=\"_blank\" rel=\"noopener\">PDF</a>':'')+\n            '<button class=\"btn ghost sm\" onclick=\"mQuoteViewer('+jsArg(q.quoteNo)+','+q.rev+')\">Open</button></div>';\n        });\n        html += '</div>';\n      });\n    }\n    html += '</div>';\n\n    // history\n    html += '<div class=\"card\"><div class=\"ovl\">History</div>';\n    if(!(d.history||[]).length) html += '<div class=\"empty\">No activity logged yet.</div>';\n    else{\n      html += '<ul class=\"tlx\">';\n      d.history.forEach(function(r){ html += '<li><div class=\"w\">'+esc(r.when)+' · '+esc(r.who)+' · '+esc(r.action)+'</div><div class=\"d\">'+esc(r.details)+'</div>'+(r.note?'<div class=\"d\" style=\"margin-top:4px;font-style:italic;white-space:pre-wrap\">'+esc(r.note)+'</div>':'')+attachmentLinksHtml(r.attachments)+'</li>'; });\n      html += '</ul>';\n    }\n    html += '</div>';\n    setHtml('main', html);\n}\nfunction mEditCase(o){\n  openModal('Edit case',\n    '<div class=\"frow\"><div><label class=\"req\">Title</label><input id=\"fo_title\" value=\"'+esc(o.title)+'\"></div></div>'+\n    '<div class=\"frow\"><div><label>Details</label><textarea id=\"fo_det\">'+esc(o.details||'')+'</textarea></div></div>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn\" onclick=\"saveEditCase('+jsArg(o.id)+')\">Save</button>', true);\n}\nfunction saveEditCase(id){\n  var d = {title:v('fo_title'), details:v('fo_det')};\n  gs('api_updateCase', id, d).then(function(){ closeModal(); toast('Saved.'); vCase(id); }).catch(oops);\n}\nfunction mAssignCase(){\n  var d=CUR.caseData; if(!d) return;\n  var sug=(d.case.ownerList||[]).map(function(o){ return {name:o.name, email:o.email}; });\n  mAssign(d.case.id, sug);\n}\nfunction mAssign(id, suggestions){\n  S._wk={ id:id, pick:null, sug:suggestions||[] };\n  ensureUsers().then(function(){\n    var bubbles = S._wk.sug.length\n      ? '<div class=\"hint\" style=\"margin:0\">Suggested — people who own this case</div><div class=\"bubbles\">'+\n        S._wk.sug.map(function(o){ return '<button type=\"button\" class=\"bub\" onclick=\"wkPick('+jsArg(o.email)+','+jsArg(o.name)+')\">'+esc(o.name)+'</button>'; }).join('')+'</div>'\n      : '';\n    openModal('Reassign ticket',\n      bubbles+\n      '<label style=\"margin-top:10px\">Search for a user</label>'+\n      '<input id=\"wk_q\" autocomplete=\"off\" oninput=\"wkSearch()\">'+\n      '<div id=\"wk_res\" class=\"reslist\"></div>'+\n      '<div id=\"wk_sel\" class=\"hint\" style=\"margin-top:8px\">No one selected yet.</div>'+\n      '<div class=\"frow\" style=\"margin-top:10px\"><div><label>Handover note <span class=\"sub\">(optional)</span></label>'+\n      '<textarea id=\"wk_note\" maxlength=\"2000\"></textarea></div></div>'+\n      '<div class=\"frow\" style=\"margin-top:10px\"><div><label>Attachments <span class=\"sub\">(optional, any type, up to 100 MB each)</span></label>'+\n      '<input id=\"wk_files\" type=\"file\" multiple onchange=\"wkFilesPicked()\">'+\n      '<div id=\"wk_filelist\" class=\"hint\"></div></div></div>'+\n      '<p class=\"hint\">Any CRM user can hold this ticket; ownership is unchanged.</p>',\n      '<button class=\"btn ghost\" id=\"wk_cancel\" style=\"display:none\" onclick=\"wkCancelUpload()\">Cancel upload</button>'+\n      '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n      '<button class=\"btn\" id=\"wk_go\" disabled onclick=\"doAssign()\">Reassign</button>');\n    wkSearch();\n    el('wk_q').focus();\n  }).catch(oops);\n}\nfunction wkFileRowHtml(f, i, pct){\n  return '<div id=\"wk_frow_'+i+'\">'+esc(f.name)+' — '+fmtBytes(f.size)+(pct===undefined||pct===null?'':' — '+pct+'%')+'</div>';\n}\nfunction wkFilesPicked(){\n  var input = el('wk_files');\n  var files = input ? Array.prototype.slice.call(input.files) : [];\n  setHtml('wk_filelist', files.length\n    ? files.map(function(f,i){ return wkFileRowHtml(f,i); }).join('')\n    : '');\n}\nfunction wkSetProgress(i, file, pct){\n  var row = el('wk_frow_'+i);\n  if(row) row.outerHTML = wkFileRowHtml(file, i, pct);\n}\nfunction wkSearch(){\n  var q=low(v('wk_q'));\n  var list=(S.users||[]).filter(function(u){ return !q || low(u.name).indexOf(q)>-1 || low(u.email).indexOf(q)>-1; }).slice(0,8);\n  setHtml('wk_res', list.length\n    ? list.map(function(u){ return '<div class=\"resrow'+((S._wk.pick&&low(S._wk.pick.email)===low(u.email))?' on':'')+'\" onclick=\"wkPick('+jsArg(u.email)+','+jsArg(u.name)+')\"><b>'+esc(u.name)+'</b> <span class=\"sub\">'+esc(u.email)+'</span></div>'; }).join('')\n    : '<div class=\"sub\" style=\"padding:8px 10px\">No matching users.</div>');\n}\nfunction wkPick(email,name){\n  S._wk.pick={email:email,name:name};\n  setHtml('wk_sel', 'Reassign to: <b>'+esc(name)+'</b>');\n  el('wk_go').disabled=false;\n  wkSearch();\n}\nvar MAX_ATTACHMENT_BYTES = 100*1024*1024;\nfunction doAssign(){\n  if(!S._wk || !S._wk.pick){ toast('Pick a user first.', true); return; }\n  var id=S._wk.id, nm=S._wk.pick.name, email=S._wk.pick.email, note=v('wk_note');\n  var input = el('wk_files');\n  var files = input ? Array.prototype.slice.call(input.files) : [];\n  for(var i=0;i<files.length;i++){\n    if(files[i].size > MAX_ATTACHMENT_BYTES){\n      toast('\"'+files[i].name+'\" is larger than 100 MB — please split or compress it first.', true);\n      return;\n    }\n  }\n  if(!files.length){\n    gs('api_assignTicket', id, email, note).then(function(){ closeModal(); toast('Ticket reassigned to '+nm+'.'); if(S.route==='case') vCase(id); else vDash(); }).catch(oops);\n    return;\n  }\n  wkUploadAndAssign(id, email, note, nm, files);\n}\nfunction wkSetUploading(on){\n  var go = el('wk_go'), cancel = el('wk_cancel');\n  if(go) go.disabled = on || !(S._wk && S._wk.pick);\n  if(cancel) cancel.style.display = on ? '' : 'none';\n}\nfunction wkCancelUpload(){\n  if(!S._wk || !S._wk.upload) return;\n  var up = S._wk.upload;\n  up.cancelled = true;\n  up.xhrs.forEach(function(x){ try{ x.abort(); }catch(e){} });\n  wkSetUploading(false);\n  toast('Upload cancelled.');\n}\nfunction wkUploadOne(sessionUrl, file, up, i){\n  return new Promise(function(resolve, reject){\n    var xhr = new XMLHttpRequest();\n    up.xhrs.push(xhr);\n    xhr.open('PUT', sessionUrl, true);\n    xhr.setRequestHeader('Content-Type', file.type || 'application/octet-stream');\n    xhr.upload.onprogress = function(ev){\n      if(ev && ev.lengthComputable) wkSetProgress(i, file, Math.round(ev.loaded/ev.total*100));\n    };\n    xhr.onload = function(){\n      if(xhr.status>=200 && xhr.status<300){\n        var meta;\n        try{ meta = JSON.parse(xhr.responseText); }catch(e){ reject(new Error('Upload of \"'+file.name+'\" did not return file details.')); return; }\n        resolve({ fileId:meta.id, fileName:file.name, mimeType:file.type || 'application/octet-stream', sizeBytes:file.size });\n      }else{\n        reject(new Error('Could not upload \"'+file.name+'\" ('+xhr.status+').'));\n      }\n    };\n    xhr.onerror = function(){ reject(new Error('Could not upload \"'+file.name+'\".')); };\n    xhr.onabort = function(){ reject(new Error('cancelled')); };\n    xhr.send(file);\n  });\n}\nfunction wkUploadAndAssign(id, email, note, nm, files){\n  var up = { cancelled:false, xhrs:[] };\n  S._wk.upload = up;\n  wkSetUploading(true);\n  gs('api_beginAttachmentUpload', id, files.map(function(f){ return { fileName:f.name, mimeType:f.type || 'application/octet-stream', sizeBytes:f.size }; }))\n    .then(function(sessions){\n      if(up.cancelled) return Promise.reject(new Error('cancelled'));\n      return Promise.all(files.map(function(f, i){ return wkUploadOne(sessions[i].sessionUrl, f, up, i); }));\n    })\n    .then(function(uploaded){\n      if(up.cancelled) return;\n      return gs('api_assignTicket', id, email, note, uploaded).then(function(){\n        closeModal(); toast('Ticket reassigned to '+nm+'.'); if(S.route==='case') vCase(id); else vDash();\n      });\n    })\n    .catch(function(e){\n      wkSetUploading(false);\n      if(up.cancelled || (e && e.message==='cancelled')) return;\n      oops(e);\n    });\n}\nfunction doStage(id){\n  gs('api_setCaseStage', id, v('stSel'), v('stNote')).then(function(){ toast('Stage updated.'); vCase(id); }).catch(oops);\n}\nfunction doPriority(id){\n  gs('api_setCasePriority', id, v('priSel')).then(function(){ toast('Priority updated.'); vCase(id); }).catch(oops);\n}\nfunction mWon(id){\n  openModal('Mark as Won',\n    '<div class=\"frow\"><div><label class=\"req\">Order value ('+esc(S.settings.currency)+')</label><input id=\"w_val\" type=\"number\" min=\"0\"></div></div>'+\n    '<label class=\"req\">Product categories</label>'+ multiPickHTML('w_cats', catPickItems(), []) +\n    '<div class=\"frow\" style=\"margin-top:12px\"><div><label>Note (optional)</label><input id=\"w_note\"></div></div>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn\" onclick=\"doWon('+jsArg(id)+')\">Confirm Won</button>', true);\n  el('w_val').focus();\n}\nfunction doWon(id){\n  var val = v('w_val'), cats = pickerVal('w_cats');\n  if(!(Number(val)>0)){ toast('Enter the order value.', true); return; }\n  if(!cats.length){ toast('Select at least one category.', true); return; }\n  gs('api_setCaseOutcome', id, 'Won', {orderValue:val, categories:cats, note:v('w_note')}).then(function(){\n    closeModal(); toast('Marked Won.'); vCase(id);\n  }).catch(oops);\n}\nfunction mOutcomeNote(id, outcome){\n  openModal('Mark as '+outcome,\n    '<label>Note (optional)</label><input id=\"o_note\">',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn'+(outcome==='Lost'?' danger':'')+'\" onclick=\"doOutcome('+jsArg(id)+','+jsArg(outcome)+')\">Confirm</button>');\n}\nfunction doOutcome(id, outcome){\n  gs('api_setCaseOutcome', id, outcome, {note:v('o_note')}).then(function(){ closeModal(); toast('Marked '+outcome+'.'); vCase(id); }).catch(oops);\n}\nfunction reopenCase(id){\n  gs('api_setCaseOutcome', id, 'Open', {}).then(function(){ toast('Case reopened.'); vCase(id); }).catch(oops);\n}\nfunction openBuilderForCase(){\n  var d = CUR.caseData;\n  mQuoteBuilder({ customerId:d.customer.id, customerName:d.customer.name, cases:[{id:d.case.id, title:d.case.title}], caseId:d.case.id, lockCase:true });\n}\n\n/* ---------------- cases list ---------------- */\nfunction vCases(){\n  S.route='cases'; setRouteAttr('cases'); S.routeArg=null; setTab('cases');\n  var f = S.caseF;\n  var html = '<div class=\"pagehead\"><div class=\"grow\"><h1>Cases</h1>'+\n    '<div class=\"sub\">Cases on customers you can access, plus any you own.</div></div>'+\n    '<button class=\"btn\" onclick=\"mPickCustomerThenCase()\">+ New case</button></div>'+\n    '<div class=\"card\"><div class=\"filterbar\">'+\n    '<label>Search cases</label><input id=\"cf_q\" value=\"'+esc(f.q)+'\" onkeydown=\"if(event.key===\\'Enter\\')applyCaseF()\">'+\n    '<select id=\"cf_stage\" onchange=\"applyCaseF()\"><option value=\"\">All stages</option>'+\n    S.settings.stages.map(function(st){ return '<option'+(st===f.stage?' selected':'')+'>'+esc(st)+'</option>'; }).join('')+'</select>'+\n    '<select id=\"cf_outcome\" onchange=\"applyCaseF()\">'+\n    ['','Open','Won','Lost','Hold'].map(function(o){ var lbl = o===''?'All outcomes':(o==='Open'?'Open only':o); return '<option value=\"'+esc(o)+'\"'+(o===f.outcome?' selected':'')+'>'+esc(lbl)+'</option>'; }).join('')+'</select>'+\n    '<select id=\"cf_priority\" onchange=\"applyCaseF()\"><option value=\"\">All priorities</option>'+\n    (S.settings.priorities || ['High','Medium','Low']).map(function(p){ return '<option'+(p===f.priority?' selected':'')+'>'+esc(p)+'</option>'; }).join('')+'</select>'+\n    /* P6: two independent boxes, OR-combined by the server. Both unticked =\n       every case visible to me. The sizing lives in the stylesheet now - the\n       inline width:auto this replaces lost to `.filterbar input`. */\n    '<label class=\"cbx\"><input type=\"checkbox\" id=\"cf_owned\"'+(f.owned?' checked':'')+' onchange=\"applyCaseF()\"> Owned by me</label>'+\n    '<label class=\"cbx\"><input type=\"checkbox\" id=\"cf_assigned\"'+(f.assigned?' checked':'')+' onchange=\"applyCaseF()\"> Assigned to me</label>'+\n    '<button class=\"btn sm\" onclick=\"applyCaseF()\">Apply</button></div>'+\n    '<div id=\"caseRes\"><div class=\"empty\">Loading…</div></div></div>';\n  setHtml('main', html);\n  loadCases();\n}\nfunction applyCaseF(){\n  S.caseF = { q:v('cf_q'), stage:v('cf_stage'), outcome:v('cf_outcome'), priority:v('cf_priority'),\n              owned:!!(el('cf_owned') && el('cf_owned').checked),\n              assigned:!!(el('cf_assigned') && el('cf_assigned').checked) };\n  loadCases();\n}\nfunction loadCases(){\n  var key=JSON.stringify(S.caseF);\n  var have = (CACHE.cases && CACHE.casesKey===key) ? CACHE.cases : null;\n  if(have) renderCases(have);\n  else if(el('caseRes')) setHtml('caseRes', '<div class=\"sub\">Loading…</div>');\n  if(have && fresh(CACHE.casesAt)) return;\n  gs('api_listCases', S.caseF).then(function(list){\n    CACHE.cases=list; CACHE.casesAt=Date.now(); CACHE.casesKey=key;\n    if(S.route!=='cases') return;\n    if(have && sameData(have,list)) return;\n    renderCases(list);\n  }).catch(function(e){\n    if(have) return;\n    if(el('caseRes')) setHtml('caseRes', '<div class=\"empty\">'+esc(errMsg(e))+'<div style=\"margin-top:10px\"><button class=\"btn ghost sm\" onclick=\"loadCases()\">Retry</button></div></div>');\n  });\n}\nfunction renderCases(list){\n    if(!el('caseRes')) return;\n    if(!list.length){ setHtml('caseRes', '<div class=\"empty\">No cases match these filters.</div>'); return; }\n    var html = '<div style=\"overflow-x:auto\"><table><tr><th>ID</th><th>Title</th><th>Customer</th><th>Status</th><th>Priority</th><th class=\"tnum-r\">Value</th><th>Owners</th><th>Assigned to</th><th>Updated</th></tr>';\n    list.forEach(function(o){\n      var val = o.outcome==='Won' ? o.orderValue : '';\n      html += '<tr class=\"clk\" onclick=\"nav(\\'case\\','+jsArg(o.id)+')\">'+\n        '<td class=\"mono\">'+esc(o.id)+'</td><td><b>'+esc(o.title)+'</b></td>'+\n        '<td>'+esc(o.customerName)+'</td>'+\n        '<td>'+caseStatusChip(o.stage,o.outcome)+'</td><td>'+(priChip(o.priority)||'<span class=\"sub\">—</span>')+'</td>'+\n        '<td class=\"tnum-r\">'+caseValueCell(o)+'</td>'+\n        '<td class=\"sub\">'+esc((o.owners||[]).join(', ')||'—')+'</td>'+\n        '<td class=\"sub\">'+(o.outcome ? '<span class=\"sub\">—</span>' : esc(o.assignee||'—'))+'</td>'+\n        '<td class=\"sub mono\">'+esc(o.updatedOn)+'</td></tr>';\n    });\n    setHtml('caseRes', html+'</table></div><div class=\"hint\">Showing up to 300 cases.</div>');\n}\n\n/* =====================================================================\n * MOBILE QUICK LOG\n * =================================================================== */\nvar QL = { customerId:'', customerName:'', newMode:false };\nfunction mQuickLog(){\n  QL = { customerId:'', customerName:'', newMode:false };\n  var body =\n    '<div id=\"ql_cust\"></div>'+\n    '<div class=\"frow\" style=\"margin-top:6px\"><div style=\"flex:2\"><label class=\"req\">Case title</label><input id=\"ql_title\"></div>'+\n    '<div><label>Stage</label><select id=\"ql_stage\">'+selOptions(S.settings.stages, 'Lead')+'</select></div>'+\n    '<div><label>Priority</label><select id=\"ql_casepri\"><option value=\"\">— none —</option>'+ selOptions(S.settings.priorities || ['High','Medium','Low'], '') +'</select></div></div>'+\n    ''\n  openModal('Quick log a case', body,\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn\" id=\"ql_save\" onclick=\"saveQuickLog()\">Log case</button>');\n  renderQLCust();\n}\nfunction renderQLCust(){\n  if(QL.customerId){\n    setHtml('ql_cust', '<label>Customer</label><div class=\"qr\"><div style=\"flex:1\"><b>'+esc(QL.customerName)+'</b></div>'+\n      '<button class=\"btn ghost sm\" onclick=\"qlClear()\">Change</button></div>');\n    return;\n  }\n  if(QL.newMode){\n    setHtml('ql_cust', '<label class=\"req\">New customer name</label><input id=\"ql_cname\">'+\n      '<div class=\"frow\" style=\"margin-top:8px\"><div><label>Location</label><select id=\"ql_tag\"><option value=\"\">—</option>'+selOptions(S.settings.tags,'')+'</select></div>'+\n      '<div><label>Type</label><select id=\"ql_type\"><option value=\"\">—</option>'+selOptions(S.settings.types,'')+'</select></div>'+\n      '<div><label>Priority</label><select id=\"ql_pri\"><option value=\"\">—</option>'+selOptions(S.settings.priorities,'')+'</select></div></div>'+\n      '<button class=\"btn lk\" onclick=\"qlToSearch()\">← search existing instead</button>');\n    setTimeout(function(){ if(el('ql_cname')) el('ql_cname').focus(); },50);\n    return;\n  }\n  setHtml('ql_cust', '<label class=\"req\">Customer</label><input id=\"ql_q\" oninput=\"qlSearch()\">'+\n    '<div id=\"ql_res\" class=\"ql-res\" style=\"display:none\"></div>'+\n    '<button class=\"btn lk\" style=\"margin-top:6px\" onclick=\"qlNew()\">+ New customer instead</button>');\n  setTimeout(function(){ if(el('ql_q')) el('ql_q').focus(); },50);\n}\nfunction qlClear(){ QL.customerId=''; QL.customerName=''; QL.newMode=false; renderQLCust(); }\nfunction qlNew(){ QL.newMode=true; renderQLCust(); }\nfunction qlToSearch(){ QL.newMode=false; renderQLCust(); }\nvar qlT=null;\nfunction qlSearch(){ clearTimeout(qlT); qlT=setTimeout(qlRun,300); }\nfunction qlRun(){\n  var q=v('ql_q'); if(q.length<2){ el('ql_res').style.display='none'; return; }\n  gs('api_searchCustomers', q).then(function(list){\n    if(v('ql_q')!==q) return;\n    el('ql_res').style.display='block';\n    if(!list.length){ setHtml('ql_res', '<div class=\"empty\">No matches. Use “+ New customer”.</div>'); return; }\n    setHtml('ql_res', list.slice(0,8).map(function(c){\n      var ok = c.access==='FULL';\n      return '<div class=\"qr\"'+(ok?' onclick=\"qlPick('+jsArg(c.id)+','+jsArg(c.name)+')\"':' style=\"opacity:.55\"')+'>'+\n        '<div style=\"flex:1\"><b>'+esc(c.name)+'</b> '+tagChips(c.tags)+'</div>'+(ok?'':'<span class=\"badge b-grey\">no access</span>')+'</div>';\n    }).join(''));\n  }).catch(oops);\n}\nfunction qlPick(id, name){ QL.customerId=id; QL.customerName=name; renderQLCust(); }\nfunction saveQuickLog(){\n  var p = { title:v('ql_title'), stage:v('ql_stage'), priority:v('ql_casepri') };\n  if(!p.title){ toast('Enter a case title.', true); return; }\n  if(QL.customerId){ p.customerId = QL.customerId; }\n  else if(QL.newMode){\n    var nm = v('ql_cname');\n    if(!nm){ toast('Enter the new customer name.', true); return; }\n    p.newCustomer = { name:nm, tag:v('ql_tag'), type:v('ql_type'), priority:v('ql_pri') };\n  }else{ toast('Pick a customer or add a new one.', true); return; }\n  el('ql_save').disabled = true;\n  gs('api_quickLog', p).then(function(r){ closeModal(); toast('Case logged — '+r.caseId); nav('case', r.caseId); })\n    .catch(function(e){ el('ql_save').disabled=false; oops(e); });\n}\n\n/* =====================================================================\n * QUOTE BUILDER  (preserved; references CaseID)\n * =================================================================== */\nvar B = null;\nfunction mQuoteBuilder(ctx){\n  // ctx: {customerId, customerName, cases[], caseId?, lockCase?, base?}\n  B = { ctx: ctx, blocks: (ctx.base && ctx.base.blocks && ctx.base.blocks.length ? ctx.base.blocks.map(function(b){ return {title:b.title||'', text: blockToText(b)}; }) : [{title:'', text:''}]) };\n  var base = ctx.base||{};\n  var caseSel = '<select id=\"qb_case\"'+(ctx.lockCase?' disabled':'')+'>';\n  if(!ctx.lockCase) caseSel += '<option value=\"\">— create a new case automatically —</option>';\n  (ctx.cases||[]).forEach(function(o){ caseSel += '<option value=\"'+esc(o.id)+'\"'+(ctx.caseId===o.id?' selected':'')+'>'+esc(o.id)+' — '+esc(o.title)+'</option>'; });\n  caseSel += '</select>';\n\n  var body =\n    '<div class=\"frow\"><div><label>Customer</label><input value=\"'+esc(ctx.customerName)+'\" disabled></div>'+\n    '<div style=\"flex:1.4\"><label>Case</label>'+caseSel+'</div></div>'+\n    '<div class=\"frow\"><div style=\"flex:2\"><label class=\"req\">Quotation title</label><input id=\"qb_title\" value=\"'+esc(base.title||'')+'\"></div>'+\n    '<div><label class=\"req\">Template</label><select id=\"qb_tpl\"><option value=\"\">Loading templates…</option></select></div></div>'+\n    '<div class=\"frow\"><div><label>Valid until</label><input id=\"qb_valid\" type=\"date\" value=\"'+esc(base.validUntil||'')+'\"></div>'+\n    '<div><label class=\"req\">Subtotal</label><input id=\"qb_sub\" type=\"number\" min=\"0\" step=\"0.01\" value=\"'+esc(base.subtotal!==undefined?base.subtotal:'')+'\" oninput=\"qbTotals()\"></div>'+\n    '<div><label>GST %</label><input id=\"qb_tax\" type=\"number\" min=\"0\" step=\"0.01\" value=\"'+esc(base.taxPct!==undefined?base.taxPct:S.settings.taxPct)+'\" oninput=\"qbTotals()\"></div>'+\n    '<div><label>Currency</label><input id=\"qb_cur\" value=\"'+esc(base.currency||S.settings.currency)+'\"></div></div>'+\n    '<div class=\"frow\"><div><label>Notes / terms shown on quote</label><textarea id=\"qb_notes\">'+esc(base.notes||'')+'</textarea></div></div>'+\n    '<div class=\"card\" style=\"background:#FAFBFA;padding:14px\"><div class=\"ovl\">BOQ tables — paste from Excel</div>'+\n    '<p class=\"hint\" style=\"margin-top:-4px\">Paste each table from Excel — the first pasted row is used as the column headers. Add a separate table for each section. The subtotal above is entered manually.</p>'+\n    '<div id=\"qb_blocks\"></div>'+\n    '<button class=\"btn ghost sm\" onclick=\"qbAddBlock()\" style=\"margin-top:8px\">+ Add another BOQ table</button></div>'+\n    '<div class=\"ovl\" style=\"margin-top:8px\">Totals</div>'+\n    '<div id=\"qb_tot\" style=\"border-top:1.5px solid var(--line);padding-top:8px\"></div>';\n\n  openModal(base.quoteNo ? 'New revision of '+base.quoteNo : 'New quotation', body,\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn\" id=\"qb_save\" onclick=\"saveQuote()\">'+(base.quoteNo?'Save revision':'Save quotation')+'</button>', true);\n\n  qbRenderBlocks(); qbTotals();\n  gs('api_listTemplates').then(function(list){\n    var sel = el('qb_tpl'); if(!sel) return;\n    var html = '<option value=\"\">— choose template —</option>';\n    list.forEach(function(t){ html += '<option value=\"'+esc(t.id)+'\"'+(base.templateId===t.id?' selected':'')+'>'+esc(t.name)+'</option>'; });\n    sel.innerHTML = html;\n    if(!list.length) sel.innerHTML = '<option value=\"\">No templates configured - add templates in Admin settings.</option>';\n  }).catch(oops);\n}\n\nfunction blockToText(b){\n  if(!b || !b.headers || !b.headers.length) return '';\n  return [b.headers.join('\\t')].concat((b.rows||[]).map(function(r){ return r.join('\\t'); })).join('\\n');\n}\nfunction parseBlockText(text){\n  var lines = String(text||'').split(/\\r?\\n/).map(function(l){ return l.replace(/\\u00A0/g,' '); }).filter(function(l){ return l.trim()!==''; });\n  if(!lines.length) return {headers:[], rows:[]};\n  var grid = lines.map(function(l){ return l.indexOf('\\t')>-1 ? l.split('\\t') : l.split(','); });\n  var cols=0; grid.forEach(function(r){ if(r.length>cols) cols=r.length; });\n  grid = grid.map(function(r){ while(r.length<cols) r.push(''); return r.map(function(c){ return String(c).trim(); }); });\n  var headers = grid[0].slice();\n  while(headers.length && headers[headers.length-1]==='') headers.pop();\n  var rows = grid.slice(1).map(function(r){ return r.slice(0,headers.length); }).filter(function(r){ return r.join('').trim()!==''; });\n  return {headers:headers, rows:rows};\n}\nfunction captureBlocks(){\n  B.blocks.forEach(function(b,i){ var t=el('qb_bt_'+i), x=el('qb_bx_'+i); if(t) b.title=t.value; if(x) b.text=x.value; });\n}\nfunction qbRenderBlocks(){\n  var html='';\n  B.blocks.forEach(function(b,i){\n    html+='<div class=\"card\" style=\"padding:12px;margin-bottom:10px;background:#fff\">'+\n      '<div class=\"frow\" style=\"margin-bottom:8px\"><div style=\"flex:2\"><label>Table title (optional)</label><input id=\"qb_bt_'+i+'\" value=\"'+esc(b.title||'')+'\" oninput=\"captureBlocks()\"></div>'+\n      (B.blocks.length>1?'<div style=\"flex:0;display:flex;align-items:flex-end\"><button class=\"btn danger sm\" onclick=\"qbDelBlock('+i+')\">Remove</button></div>':'')+'</div>'+\n      '<label>Paste table from Excel</label>'+\n      '<textarea id=\"qb_bx_'+i+'\" style=\"min-height:80px;font-family:var(--mono);font-size:12px\" oninput=\"captureBlocks();qbPreview('+i+')\">'+esc(b.text||'')+'</textarea>'+\n      '<div id=\"qb_bp_'+i+'\" style=\"margin-top:8px;overflow-x:auto\"></div></div>';\n  });\n  setHtml('qb_blocks', html);\n  B.blocks.forEach(function(b,i){ qbPreview(i); });\n}\nfunction qbPreview(i){\n  var node=el('qb_bp_'+i); if(!node) return;\n  var x=el('qb_bx_'+i); var text=x?x.value:(B.blocks[i]?B.blocks[i].text:'');\n  var pr=parseBlockText(text);\n  if(!pr.headers.length){ node.innerHTML='<span class=\"hint\">No rows yet — paste a table above.</span>'; return; }\n  var html='<table class=\"lines\"><tr>'+pr.headers.map(function(h){ return '<th>'+esc(h)+'</th>'; }).join('')+'</tr>';\n  pr.rows.slice(0,6).forEach(function(r){ html+='<tr>'+r.map(function(c){ return '<td>'+esc(c)+'</td>'; }).join('')+'</tr>'; });\n  html+='</table><div class=\"hint\">'+pr.rows.length+' row'+(pr.rows.length===1?'':'s')+(pr.rows.length>6?' (showing 6)':'')+'.</div>';\n  node.innerHTML=html;\n}\nfunction qbAddBlock(){ captureBlocks(); B.blocks.push({title:'',text:''}); qbRenderBlocks(); }\nfunction qbDelBlock(i){ captureBlocks(); B.blocks.splice(i,1); if(!B.blocks.length) B.blocks.push({title:'',text:''}); qbRenderBlocks(); }\nfunction qbTotals(){\n  if(!el('qb_tot')) return;\n  var sub=Number(v('qb_sub'))||0, tax=Number(v('qb_tax'))||0, cur=v('qb_cur')||'INR';\n  var ta=sub*tax/100;\n  setHtml('qb_tot', '<div class=\"totrow\"><span>Subtotal</span><b class=\"money\">'+esc(cur)+' '+fmtMoney(sub)+'</b></div>'+\n    '<div class=\"totrow\"><span>GST @ '+esc(tax)+'%</span><b class=\"money\">'+esc(cur)+' '+fmtMoney(ta)+'</b></div>'+\n    '<div class=\"totrow\" style=\"font-size:15px\"><span><b>Total</b></span><b class=\"money\">'+esc(cur)+' '+fmtMoney(sub+ta)+'</b></div>');\n}\nfunction saveQuote(){\n  captureBlocks();\n  var blocks = B.blocks.map(function(b){ var pr=parseBlockText(b.text); return {title:b.title||'', headers:pr.headers, rows:pr.rows}; }).filter(function(b){ return b.headers.length; });\n  if(!blocks.length){ toast('Paste at least one BOQ table (the first pasted row is the headers).', true); return; }\n  if(!v('qb_title')){ toast('Give the quotation a title.', true); return; }\n  if(!v('qb_tpl')){ toast('Choose a template (needed to generate the document).', true); return; }\n  if(v('qb_sub')==='' || !(Number(v('qb_sub'))>=0)){ toast('Enter the subtotal amount.', true); return; }\n  var p = {\n    customerId: B.ctx.customerId,\n    caseId: B.ctx.lockCase ? B.ctx.caseId : v('qb_case'),\n    baseQuoteNo: (B.ctx.base && B.ctx.base.quoteNo) || '',\n    title: v('qb_title'), templateId: v('qb_tpl'),\n    blocks: blocks, subtotal: v('qb_sub'), taxPct: v('qb_tax'), currency: v('qb_cur'),\n    validUntil: v('qb_valid'), notes: v('qb_notes')\n  };\n  el('qb_save').disabled = true;\n  gs('api_createQuotation', p).then(function(r){ toast('Saved '+r.quoteNo+' R'+r.rev+'.'); refreshBehind(); mQuoteViewer(r.quoteNo, r.rev); })\n    .catch(function(e){ el('qb_save').disabled=false; oops(e); });\n}\nfunction refreshBehind(){\n  if(S.route==='case' && S.routeArg) vCase(S.routeArg);\n  else if(S.route==='customer' && S.routeArg) vCustomer(S.routeArg);\n  else if(S.route==='cases') loadCases();\n  else if(S.route==='dash') vDash();\n}\n\n/* =====================================================================\n * QUOTE VIEWER  (preserved)\n * =================================================================== */\n/* ---- upload an externally prepared quotation ---- */\nfunction uploadCtx(){\n  if(S.route==='case' && CUR.caseData){\n    var d=CUR.caseData;\n    return { customerId:d.customer.id, customerName:d.customer.name, caseId:d.case.id, lockCase:true, cases:[{id:d.case.id,title:d.case.title}] };\n  }\n  if(S.route==='customer' && CUR.customer){\n    var x=CUR.customer;\n    var cases=(x.cases||[]).filter(function(o){ return o.outcome!=='Won' && o.outcome!=='Lost'; }).map(function(o){ return {id:o.id,title:o.title}; });\n    return { customerId:x.customer.id, customerName:x.customer.name, caseId:'', lockCase:false, cases:cases };\n  }\n  return null;\n}\nfunction mUploadQuote(base){\n  var ctx = uploadCtx();\n  if(!ctx){ toast('Open a customer or case first.', true); return; }\n  base = base || {};\n  UQ = { ctx:ctx, base:base };\n  var caseSel = '<select id=\"uq_case\"'+(ctx.lockCase||base.quoteNo?' disabled':'')+'>';\n  if(!ctx.lockCase && !base.quoteNo) caseSel += '<option value=\"\">— create a new case automatically —</option>';\n  (ctx.cases||[]).forEach(function(o){ caseSel += '<option value=\"'+esc(o.id)+'\"'+((base.caseId||ctx.caseId)===o.id?' selected':'')+'>'+esc(o.id)+' — '+esc(o.title)+'</option>'; });\n  caseSel += '</select>';\n  openModal(base.quoteNo ? 'Upload new revision of '+base.quoteNo : 'Upload quotation (prepared outside the CRM)',\n    '<p class=\"hint\" style=\"margin-top:0\">Attach a quotation you prepared elsewhere (PDF, Word or Excel) so it is on record against the case. The file is stored in the Supabase database and can be downloaded from this CRM.</p>'+\n    '<div class=\"frow\"><div><label>Customer</label><input value=\"'+esc(ctx.customerName)+'\" disabled></div>'+\n    '<div style=\"flex:1.4\"><label>Case</label>'+caseSel+'</div></div>'+\n    '<div class=\"frow\"><div style=\"flex:2\"><label class=\"req\">Title</label><input id=\"uq_title\" value=\"'+esc(base.title||'')+'\"></div>'+\n    '<div><label>Status</label><select id=\"uq_status\">'+\n      ['Sent','Draft'].map(function(x){ return '<option'+(base.status===x?' selected':'')+'>'+x+'</option>'; }).join('')+'</select></div></div>'+\n    '<div class=\"frow\"><div><label class=\"req\">Total value</label><input id=\"uq_total\" type=\"number\" min=\"0\" step=\"0.01\" value=\"'+esc(base.total!==undefined?base.total:'')+'\"></div>'+\n    '<div><label>Currency</label><input id=\"uq_cur\" value=\"'+esc(base.currency||S.settings.currency)+'\"></div>'+\n    '<div><label>Valid until</label><input id=\"uq_valid\" type=\"date\" value=\"'+esc(base.validUntil||'')+'\"></div></div>'+\n    '<div class=\"frow\"><div><label class=\"req\">File</label><input id=\"uq_file\" type=\"file\" accept=\".pdf,.doc,.docx,.xls,.xlsx\" onchange=\"uqPicked()\"><div class=\"hint\" id=\"uq_fname\">No file chosen — up to about 8 MB.</div></div></div>'+\n    '<div class=\"frow\"><div><label>Notes</label><textarea id=\"uq_notes\">'+esc(base.notes||'')+'</textarea></div></div>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn\" id=\"uq_save\" onclick=\"saveUpload()\">Upload quotation</button>', true);\n  el('uq_title').focus();\n}\nvar UQ = null;\nfunction uqPicked(){\n  var f = el('uq_file').files[0];\n  if(!f){ setText('uq_fname', 'No file chosen — up to about 8 MB.'); return; }\n  setText('uq_fname', f.name+' — '+Math.round(f.size/1024)+' KB');\n}\nfunction saveUpload(){\n  var f = el('uq_file').files[0];\n  if(!f){ toast('Choose a file to upload.', true); return; }\n  if(f.size > 8*1024*1024){ toast('That file is larger than 8 MB — please compress it first.', true); return; }\n  if(!v('uq_title')){ toast('Give the quotation a title.', true); return; }\n  if(v('uq_total')==='' || !(Number(v('uq_total'))>=0)){ toast('Enter the total value.', true); return; }\n  var btn = el('uq_save'); btn.disabled = true; btn.textContent = 'Uploading…';\n  var fr = new FileReader();\n  fr.onerror = function(){ btn.disabled=false; btn.textContent='Upload quotation'; toast('Could not read that file.', true); };\n  fr.onload = function(){\n    var b64 = String(fr.result).split(',')[1];\n    var p = {\n      customerId: UQ.ctx.customerId,\n      caseId: (UQ.ctx.lockCase || UQ.base.quoteNo) ? (UQ.base.caseId || UQ.ctx.caseId) : v('uq_case'),\n      baseQuoteNo: UQ.base.quoteNo || '',\n      title: v('uq_title'), status: v('uq_status'),\n      total: v('uq_total'), currency: v('uq_cur'), validUntil: v('uq_valid'), notes: v('uq_notes'),\n      fileName: f.name, mimeType: f.type || 'application/octet-stream', dataB64: b64\n    };\n    gs('api_uploadQuotation', p).then(function(r){\n      toast('Uploaded '+r.quoteNo+' R'+r.rev+'.'); refreshBehind(); mQuoteViewer(r.quoteNo, r.rev);\n    }).catch(function(e){ btn.disabled=false; btn.textContent='Upload quotation'; oops(e); });\n  };\n  fr.readAsDataURL(f);\n}\n\nfunction mQuoteViewer(quoteNo, rev){\n  openModal(quoteNo+' · R'+rev, '<div class=\"sub\">Loading quotation…</div>', '', true);\n  gs('api_getQuotation', quoteNo, rev).then(function(d){\n    CUR.quote = d;\n    var q = d.quote;\n    var html = '<div style=\"display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:10px\">'+\n      qStatusChip(q.status)+'<b>'+esc(q.title)+'</b><span class=\"sub\">for '+esc(d.customer.name)+'</span>'+\n      '<span class=\"sub mono\" style=\"margin-left:auto\">'+esc(q.date)+' · '+esc(q.by)+'</span></div>';\n\n    var ext = q.source==='External';\n    if(ext){\n      html += '<div class=\"card\" style=\"padding:12px 16px;border-left:4px solid var(--blue)\"><b>External quotation</b> <span class=\"sub\">— prepared outside the CRM'+(q.fileName?': '+esc(q.fileName):'')+'</span></div>';\n    }\n    (d.blocks||[]).forEach(function(blk){\n      if(blk.title) html += '<div class=\"ovl\" style=\"margin-top:12px\">'+esc(blk.title)+'</div>';\n      html += '<div style=\"overflow-x:auto\"><table class=\"lines\"><tr>'+blk.headers.map(function(h){ return '<th>'+esc(h)+'</th>'; }).join('')+'</tr>';\n      blk.rows.forEach(function(r){ html += '<tr>'+r.map(function(c){ return '<td>'+esc(c)+'</td>'; }).join('')+'</tr>'; });\n      html += '</table></div>';\n    });\n    html += '<div style=\"border-top:1.5px solid var(--line);margin-top:8px;padding-top:8px\">'+\n      (ext ? '' :\n        '<div class=\"totrow\"><span>Subtotal</span><b class=\"money\">'+esc(q.currency)+' '+fmtMoney(q.subtotal)+'</b></div>'+\n        '<div class=\"totrow\"><span>GST @ '+esc(q.taxPct)+'%</span><b class=\"money\">'+esc(q.currency)+' '+fmtMoney(q.taxAmount)+'</b></div>')+\n      '<div class=\"totrow\" style=\"font-size:15px\"><span><b>Total</b></span><b class=\"money\">'+esc(q.currency)+' '+fmtMoney(q.total)+'</b></div></div>';\n\n    html += '<div class=\"kv\" style=\"margin-top:12px\">'+\n      '<b>Case</b><span class=\"mono\"><a onclick=\"closeModal();nav(\\'case\\','+jsArg(q.caseId)+')\" style=\"cursor:pointer\">'+esc(q.caseId)+'</a></span>'+\n      '<b>'+(ext?'File':'Template')+'</b><span>'+esc(ext?(q.fileName||'—'):(q.templateName||'—'))+'</span>'+\n      '<b>Valid until</b><span>'+esc(q.validUntil||'—')+'</span>'+\n      '<b>Notes</b><span>'+esc(q.notes||'—')+'</span></div>';\n\n    if(q.doc||q.pdf){\n      html += '<div style=\"margin-top:12px;display:flex;gap:10px;flex-wrap:wrap\">'+\n        (q.doc?'<a class=\"btn ghost sm\" href=\"'+esc(q.doc)+'\" target=\"_blank\" rel=\"noopener\">Download document</a>':'')+\n        (q.pdf?'<a class=\"btn ghost sm\" href=\"'+esc(q.pdf)+'\" target=\"_blank\" rel=\"noopener\">'+(ext?'Download uploaded file':'Download PDF')+'</a>':'')+'</div>';\n    }\n    html += '<div style=\"margin-top:8px;display:flex;gap:10px;flex-wrap:wrap\">'+\n      (q.driveViewLink\n        ? '<a class=\"btn ghost sm\" href=\"'+esc(q.driveViewLink)+'\" target=\"_blank\" rel=\"noopener\">View in Drive</a>'\n        : (driveHosted(q) ? '' : '<button class=\"btn ghost sm\" id=\"driveSaveBtn\" onclick=\"saveQuoteToDrive('+jsArg(quoteNo)+','+rev+')\">Save to Drive</button>'))+\n      '</div>';\n    if(d.revisions.length>1){\n      html += '<div class=\"ovl\" style=\"margin-top:16px\">All revisions</div>';\n      d.revisions.forEach(function(r){\n        var cur = r.rev===q.rev;\n        html += '<div class=\"qr\"'+(cur?' style=\"border-color:var(--brand)\"':'')+'><span class=\"mono\">R'+r.rev+'</span>'+qStatusChip(r.status)+\n          '<span class=\"sub mono\">'+esc(r.date)+'</span><span class=\"money\" style=\"margin-left:auto\">'+esc(q.currency)+' '+fmtMoney(r.total)+'</span>'+\n          (cur?'<span class=\"badge b-green\">Viewing</span>':'<button class=\"btn ghost sm\" onclick=\"mQuoteViewer('+jsArg(quoteNo)+','+r.rev+')\">View</button>')+'</div>';\n      });\n    }\n\n    var foot = '<button class=\"btn ghost\" onclick=\"closeModal()\">Close</button>';\n    foot += '<button class=\"btn ghost\" onclick=\"newRevision()\">New revision</button>';\n    if(!ext && (q.status==='Draft'||q.status==='Sent')) foot += '<button class=\"btn ghost\" id=\"genBtn\" onclick=\"genDoc('+jsArg(quoteNo)+','+rev+')\">'+(q.doc?'Re-generate download':'Generate download')+'</button>';\n    if(q.status==='Draft') foot += '<button class=\"btn\" onclick=\"setQStatus('+jsArg(quoteNo)+','+rev+',\\'Sent\\')\">Mark Sent</button>';\n    openModal(quoteNo+' · R'+rev, html, foot, true);\n  }).catch(function(e){ closeModal(); oops(e); });\n}\nfunction driveHosted(q){\n  // Generated quotes produced by the template pipeline already live in the\n  // Drive quotations folder - doc/pdf ARE Drive links, so a separate\n  // \"Save to Drive\" step would just duplicate the file. Older quotes whose\n  // doc/pdf still point at the local download endpoint keep the button.\n  var link = String((q && (q.doc || q.pdf)) || '');\n  return q && q.source === 'Generated' && link.indexOf('drive.google.com') > -1;\n}\nfunction saveQuoteToDrive(quoteNo, rev){\n  var btn = el('driveSaveBtn');\n  if(btn){ btn.disabled = true; btn.textContent = 'Saving…'; }\n  gs('api_saveQuotationToDrive', quoteNo, rev).then(function(){\n    mQuoteViewer(quoteNo, rev);\n  }).catch(function(e){\n    if(btn){ btn.disabled = false; btn.textContent = 'Save to Drive'; }\n    oops(e);\n  });\n}\nfunction genDoc(quoteNo, rev){\n  el('genBtn').disabled = true; setText('genBtn', 'Generating…');\n  gs('api_generateQuoteDoc', quoteNo, rev).then(function(r){ toast('Download links created.'); mQuoteViewer(quoteNo, rev); })\n    .catch(function(e){ if(el('genBtn')){ el('genBtn').disabled=false; setText('genBtn', 'Generate download'); } oops(e); });\n}\nfunction setQStatus(quoteNo, rev, status){\n  gs('api_setQuoteStatus', quoteNo, rev, status).then(function(){ toast('Marked '+status+'.'); refreshBehind(); mQuoteViewer(quoteNo, rev); }).catch(oops);\n}\nfunction newRevision(){\n  var d = CUR.quote; if(!d) return;\n  var q = d.quote;\n  if(q.source==='External'){\n    closeModal();\n    mUploadQuote({ quoteNo:q.quoteNo, caseId:q.caseId, title:q.title, total:q.total, currency:q.currency, validUntil:q.validUntil, notes:q.notes, status:q.status });\n    return;\n  }\n  mQuoteBuilder({\n    customerId: '', customerName: d.customer.name,\n    cases: [{id:q.caseId, title:'(same as previous revision)'}], caseId: q.caseId, lockCase: true,\n    base: { quoteNo: q.quoteNo, title: q.title, templateId: q.templateId, taxPct: q.taxPct, currency: q.currency, validUntil: q.validUntil, notes: q.notes, blocks: d.blocks, subtotal: q.subtotal }\n  });\n  B.ctx.customerId = d.customer.id;\n}\n\n/* =====================================================================\n * ADMIN\n * =================================================================== */\nfunction vAdmin(){\n  S.route='admin'; setRouteAttr('admin'); S.routeArg=null; setTab('admin');\n  if(!isAdmin()){ setHtml('main', '<div class=\"card\"><div class=\"empty\">The Admin area needs L5.</div></div>'); return; }\n  setHtml('main', '<div class=\"pagehead\"><div class=\"grow\"><h1>Admin</h1>'+\n    '<div class=\"sub\">Users, lists, import and database links.</div></div></div><div id=\"admBody\"><div class=\"sub\">Loading…</div></div>');\n  Promise.all([ gs('api_admin_listUsers'), gs('api_admin_links').catch(function(){ return null; }) ])\n    .then(function(res){ renderAdmin(res[0], res[1]); }).catch(oops);\n}\nfunction renderAdmin(users, links){\n  var html = '<div class=\"card\"><div class=\"ovl\">Users &amp; access levels</div>';\n  html += '<table><tr><th>Email</th><th>Name</th><th>Level</th><th>Allowed locations</th><th>Status</th><th></th></tr>';\n  (users||[]).forEach(function(u){\n    var lc = u.role==='L6'?'b-green':(u.role==='L5'?'b-blue':(u.role==='L4'?'b-blue':(u.role==='L1'?'b-grey':'b-amber')));\n    html += '<tr><td class=\"mono\">'+esc(u.email)+'</td><td>'+esc(u.name)+'</td>'+\n      '<td><span class=\"badge '+lc+'\">'+esc(u.role)+'</span></td>'+\n      '<td>'+(u.allowedTags.indexOf('*')>-1?'<span class=\"chip\">All (*)</span>':tagChips(u.allowedTags))+'</td>'+\n      '<td>'+(u.active?'<span class=\"badge b-green\">Active</span>':'<span class=\"badge b-red\">Inactive</span>')+'</td>'+\n      '<td><button class=\"btn ghost sm\" onclick=\"mUser('+jsJsonArg(u)+')\">Edit</button></td></tr>';\n  });\n  html += '</table><div style=\"margin-top:10px\"><button class=\"btn\" onclick=\"mUser(null)\">+ Add user</button></div>'+\n    '<div class=\"kv\" style=\"margin-top:14px;grid-template-columns:42px 1fr\">'+\n    Object.keys({L1:1,L2:1,L3:1,L4:1,L5:1,L6:1}).map(function(k){ return '<b>'+k+'</b><span class=\"sub\">'+esc(LEVEL_DESC[k])+'</span>'; }).join('')+\n    '</div></div>';\n\n  html += '<div class=\"row\"><div class=\"col\">'+\n    configCard('Customer locations (geographies)', 'TAGS', S.settings.tags, 'Locations drive access control. Removing a location does not remove it from customers that already have it.')+\n    configCard('Customer types', 'TYPES', S.settings.types)+\n    configCard('Priorities', 'PRIORITIES', S.settings.priorities)+\n    '</div>';\n\n  html += '<div class=\"col\">'+\n    configCard('Won order categories', 'CATEGORIES', S.settings.categories, 'One per line. Shown as the multi-select when a case is marked Won.')+\n    configCard('SEI names', 'SEI_NAMES', S.settings.seiNames)+\n    '<div class=\"card\"><div class=\"ovl\">Defaults</div>'+\n    '<div class=\"frow\"><div><label>GST %</label><input id=\"ad_tax\" type=\"number\" value=\"'+esc(S.settings.taxPct)+'\"></div>'+\n    '<div><label>Currency</label><input id=\"ad_cur\" value=\"'+esc(S.settings.currency)+'\"></div></div>'+\n    '<div class=\"frow\"><div><label>Company name (on quotes)</label><input id=\"ad_co\" value=\"'+esc(S.settings.company)+'\"></div></div>'+\n    '<button class=\"btn sm\" onclick=\"saveSettings({taxPct:v(\\'ad_tax\\'),currency:v(\\'ad_cur\\'),company:v(\\'ad_co\\')})\">Save defaults</button></div></div></div>';\n\n  html += '<div class=\"card\"><div class=\"ovl\">Import customers from the sheet</div>'+\n    '<p style=\"margin-bottom:8px\">Paste rows into the Supabase <b>import_customers</b> table under these columns, then run import:</p>'+\n    '<p class=\"mono\" style=\"font-size:12px;background:#FAFBFA;border:1px solid var(--line);border-radius:7px;padding:9px\">Name · Location · Type · Priority · Area · Address · GSTIN · ContactName · ContactDesignation · ContactPhone · ContactEmail · Handlers</p>'+\n    '<p class=\"hint\">Handlers accept comma-separated emails (must be active users). Rows whose Name already exists are skipped. Processed rows are cleared from the import table. Tip: for everyday use the in-app “Bulk add” on the Customers page is faster.</p>'+\n    '<div style=\"margin-top:10px;display:flex;gap:10px;align-items:center\"><button class=\"btn\" id=\"impBtn\" onclick=\"runImport()\">Run customer import</button><span id=\"impRes\" class=\"sub\"></span></div></div>';\n\n  html += '<div class=\"card\"><div class=\"ovl\">Import contacts from the sheet</div>'+\n    '<p style=\"margin-bottom:8px\">Paste rows into the Supabase <b>import_contacts</b> table to add many contacts across customers at once:</p>'+\n    '<p class=\"mono\" style=\"font-size:12px;background:#FAFBFA;border:1px solid var(--line);border-radius:7px;padding:9px\">CustomerName · ContactName · Designation · Phone · Email · Notes</p>'+\n    '<p class=\"hint\">CustomerName must match an existing customer exactly. Unmatched rows are reported and skipped. Processed rows are cleared from the import table.</p>'+\n    '<div style=\"margin-top:10px;display:flex;gap:10px;align-items:center\"><button class=\"btn\" id=\"impcBtn\" onclick=\"runImportContacts()\">Run contact import</button><span id=\"impcRes\" class=\"sub\"></span></div></div>';\n\n  html += '<div class=\"card\"><div class=\"ovl\">Recycle bin — deleted customers</div>'+\n    '<p class=\"hint\" style=\"margin-top:-4px\">Customers moved here from the Customers grid. Restoring brings back the customer record (re-add its handlers and contacts afterwards).</p>'+\n    '<div id=\"recycleBin\"><div class=\"sub\">Loading…</div></div></div>';\n  if(links){\n    html += '<div class=\"card\"><div class=\"ovl\">Database</div>'+\n      '<div class=\"kv\">'+\n      '<b>Backend</b><span>'+esc(links.database||'Supabase Postgres')+'</span>'+\n      '<b>Project</b><span class=\"mono\">'+esc(links.supabaseUrl||'')+'</span>'+\n      '<b>Tables</b><span class=\"mono\">'+esc((links.tables||[]).join(', '))+'</span>'+\n      '</div></div>';\n  }\n  setHtml('admBody', html);\n  loadRecycle();\n}\nfunction configCard(title, key, items, hint){\n  var rows = (items||[]).map(function(item){\n    return '<div class=\"qr\"><div style=\"flex:1\">'+esc(item)+'</div>'+\n      '<button class=\"btn lk\" onclick=\"cfgRename('+jsArg(key)+','+jsArg(item)+')\">edit</button> · '+\n      '<button class=\"btn lk\" onclick=\"cfgDelete('+jsArg(key)+','+jsArg(item)+')\">delete</button></div>';\n  }).join('') || '<div class=\"empty\">Nothing configured yet.</div>';\n  return '<div class=\"card\"><div class=\"ovl\">'+esc(title)+'</div>'+rows+\n    (hint?'<p class=\"hint\">'+esc(hint)+'</p>':'')+\n    '<div class=\"frow\" style=\"margin-top:10px\"><div style=\"flex:1\"><label>New value</label><input id=\"cfg_'+key+'\"></div>'+\n    '<div style=\"display:flex;align-items:flex-end\"><button class=\"btn sm\" onclick=\"cfgAdd('+jsArg(key)+')\">Add</button></div></div></div>';\n}\nfunction cfgAdd(key){\n  var val = v('cfg_'+key);\n  if(!val){ toast('Enter a value.', true); return; }\n  gs('api_admin_addConfigItem', key, val).then(afterConfigChange).catch(oops);\n}\nfunction cfgDelete(key, item){\n  gs('api_admin_deleteConfigItem', key, item).then(afterConfigChange).catch(oops);\n}\nfunction cfgRename(key, item){\n  var next = prompt('Rename \"'+item+'\" to:', item);\n  if(next===null) return;\n  next = String(next).trim();\n  if(!next || next===item) return;\n  gs('api_admin_renameConfigItem', key, item, next).then(afterConfigChange).catch(oops);\n}\nfunction afterConfigChange(){\n  toast('Saved.');\n  cacheBust();\n  gs('api_bootstrap').then(function(b){ S.settings = b.settings; vAdmin(); }).catch(oops);\n}\nfunction loadRecycle(){\n  if(!el('recycleBin')) return;\n  gs('api_admin_listRecycle').then(renderRecycle).catch(function(e){ if(el('recycleBin')) setHtml('recycleBin', '<div class=\"empty\">'+esc(errMsg(e))+'</div>'); });\n}\nfunction renderRecycle(d){\n  if(!el('recycleBin')) return;\n  if(!d.customers.length){ setHtml('recycleBin', '<div class=\"empty\">The recycle bin is empty.</div>'); return; }\n  var html='<table><tr><th>Customer</th><th>Location</th><th>Area</th><th>Deleted</th><th></th></tr>';\n  d.customers.forEach(function(c){\n    html+='<tr><td><b>'+esc(c.name)+'</b> <span class=\"sub mono\">'+esc(c.id)+'</span></td>'+\n      '<td>'+tagChips(c.tags)+'</td><td class=\"sub\">'+esc(c.area||'—')+'</td>'+\n      '<td class=\"sub mono\">'+esc(c.deletedOn||'')+(c.deletedBy?' · '+esc(c.deletedBy):'')+'</td>'+\n      '<td><button class=\"btn ghost sm\" onclick=\"restoreCust('+jsArg(c.id)+')\">Restore</button> '+\n      '<button class=\"btn danger sm\" onclick=\"purgeCust('+jsArg(c.id)+','+jsArg(c.name)+')\">Delete forever</button></td></tr>';\n  });\n  setHtml('recycleBin', html+'</table>');\n}\nfunction restoreCust(id){\n  gs('api_admin_restoreCustomer', id).then(function(){ toast('Customer restored.'); loadRecycle(); }).catch(oops);\n}\nfunction purgeCust(id, name){\n  openModal('Delete forever',\n    '<p>Permanently delete <b>'+esc(name)+'</b> from the recycle bin? This cannot be undone.</p>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn danger\" onclick=\"purgeCust2('+jsArg(id)+')\">Delete forever</button>');\n}\nfunction purgeCust2(id){\n  gs('api_admin_purgeCustomer', id).then(function(){ closeModal(); toast('Permanently deleted.'); loadRecycle(); }).catch(oops);\n}\nfunction saveSettings(d){\n  gs('api_admin_saveSettings', d).then(function(){ toast('Settings saved.'); return gs('api_bootstrap'); })\n    .then(function(b){ S.settings = b.settings; }).catch(oops);\n}\nfunction runImport(){\n  el('impBtn').disabled = true; setText('impRes', 'Importing…');\n  gs('api_admin_runImport').then(function(r){\n    el('impBtn').disabled = false;\n    var msg = r.message ? r.message : (r.created+' created, '+r.skipped.length+' skipped'+(r.skipped.length?': '+r.skipped.join('; '):''));\n    setText('impRes', msg); toast('Import finished — '+r.created+' created.');\n  }).catch(function(e){ el('impBtn').disabled=false; setText('impRes', ''); oops(e); });\n}\nfunction runImportContacts(){\n  el('impcBtn').disabled = true; setText('impcRes', 'Importing…');\n  gs('api_admin_runImportContacts').then(function(r){\n    el('impcBtn').disabled = false;\n    var msg = r.message ? r.message : (r.created+' added, '+r.skipped.length+' skipped'+(r.skipped.length?': '+r.skipped.join('; '):''));\n    setText('impcRes', msg); toast('Contacts imported — '+r.created+' added.');\n  }).catch(function(e){ el('impcBtn').disabled=false; setText('impcRes', ''); oops(e); });\n}\nfunction mUser(u){\n  u = u||{};\n  openModal(u.email?'Edit user':'Add user',\n    '<div class=\"frow\"><div style=\"flex:1.5\"><label class=\"req\">Email</label><input id=\"au_email\" value=\"'+esc(u.email||'')+'\"'+(u.email?' disabled':'')+'></div>'+\n    '<div><label>Name</label><input id=\"au_name\" value=\"'+esc(u.name||'')+'\"></div></div>'+\n    '<div class=\"frow\"><div><label>Access level</label><select id=\"au_role\" onchange=\"userLvlHint()\">'+\n    ['L1','L2','L3','L4','L5','L6'].map(function(r){ return '<option'+(u.role===r?' selected':'')+'>'+r+'</option>'; }).join('')+\n    '</select></div>'+\n    '<div><label>Status</label><select id=\"au_active\"><option value=\"1\"'+(u.active!==false?' selected':'')+'>Active</option><option value=\"0\"'+(u.active===false?' selected':'')+'>Inactive</option></select></div></div>'+\n    '<p class=\"hint\" id=\"au_hint\" style=\"margin-top:-4px\"></p>'+\n    '<label>Allowed locations (full access to matching customers; needed for L2/L3)</label>'+\n    tagPickerHTML('au_tags', S.settings.tags, u.allowedTags||[], true)+\n    '<p class=\"hint\">L4 and L5 see everything regardless of location.</p>',\n    '<button class=\"btn ghost\" onclick=\"closeModal()\">Cancel</button>'+\n    '<button class=\"btn\" onclick=\"saveUser('+jsArg(u.email||'')+')\">Save user</button>', true);\n  userLvlHint();\n}\nfunction userLvlHint(){ var r = v('au_role'); if(el('au_hint')) setText('au_hint', LEVEL_DESC[r]||''); }\nfunction saveUser(origEmail){\n  var d = { email: origEmail || v('au_email'), name: v('au_name'), role: v('au_role'), active: v('au_active')==='1', allowedTags: pickerVal('au_tags') };\n  gs('api_admin_saveUser', d).then(function(){ closeModal(); toast('User saved.'); vAdmin(); }).catch(oops);\n}\n\n/* level descriptions mirrored client-side for the Admin UI */\nvar LEVEL_DESC = {\n  L1:'Assignments only — sees only cases assigned to them.',\n  L2:'Sales — own dashboard + assignments. Can create customers, cases, quotes, set priority, and assign to others.',\n  L3:'L2 + can view the dashboards of L2 users who share a location, and edit customer locations and type.',\n  L4:'L3 + full access to all customers and cases across all locations.',\n  L5:'L4 without a sales performance dashboard — back-office, full data access, no Admin.',\n  L6:'L5 + Admin (users, lists, import, database links). No performance dashboard.'\n};\n\n/* ---------------- go ---------------- */\nif(BOOT && BOOT.ok){ init(); } else { renderLock(); }";
